registerTemplate("web.EmojiPicker", `/web/static/src/core/emoji_picker/emoji_picker.xml`, `<t t-name="web.EmojiPicker" xml:space="preserve">
    <div t-attf-class="o-EmojiPicker d-flex flex-column justify-content-center {{ this.props.class }}" t-att-class="{ 'align-items-center': !this.emojisLoaded, 'h-100': this.props.mobile }" t-on-click="this.onClick" t-on-keydown="this.onKeydown">
        <t t-if="!this.emojisLoaded">
            <span class="o-EmojiPicker-empty">😵‍💫</span>
            <span>Failed to load emojis...</span>
        </t>
        <t t-else="">
            <div class="o-EmojiPicker-search d-flex align-items-center mx-2 mt-2 rounded">
                <span class="o-EmojiPicker-searchContour d-flex mx-1 w-100 rounded-pill o-active align-items-center justify-content-center border bg-view">
                    <i class="oi ps-2 py-1 fs-7 rounded-start-0 rounded-3 o-active opacity-50" data-icon="search" title="Search..." role="img" aria-label="Search..."/>
                    <t t-call="web.EmojiPicker.searchInput"/>
                    <button t-if="this.searchTerm()" class="btn btn-sm btn-link p-0 px-1 opacity-50 opacity-100-hover" title="Clear search" t-on-click="this.clearSearch">
                        <i class="oi oi-filled" data-icon="cancel"/>
                    </button> 
                </span>
            </div>
            <t t-set="itemIndex" t-value="0"/>
            <t t-set="_recentEmojis" t-value="this.recentEmojis()"/>
            <t t-set="currentEmojis" t-value="this.getEmojis(_recentEmojis)"/>
            <t t-set="hasEmojisFromSearch" t-value="_recentEmojis.length or currentEmojis.length"/>
            <div class="o-EmojiPicker-content overflow-auto d-flex flex-grow-1 w-100 flex-wrap align-items-center user-select-none mt-1" t-att-class="!hasEmojisFromSearch ? 'flex-column justify-content-center' : 'align-content-start'" t-ref="this.gridRef" t-on-scroll="this.highlightActiveCategory">
                <t t-if="this.searchTerm() and !hasEmojisFromSearch" class="d-flex flex-column">
                    <span class="o-EmojiPicker-empty">😢</span>
                    <span>No emojis match your search</span>
                </t>
                <t t-if="_recentEmojis.length &gt; 0">
                    <t t-if="!this.searchTerm()" t-call="web.EmojiPicker.section" category="this.recentCategory"/>
                    <t t-foreach="_recentEmojis" t-as="emoji" t-key="'recent_' + emoji_index">
                        <t t-call="web.EmojiPicker.emoji" inRecent="true" emoji="emoji"/>
                        <t t-set="itemIndex" t-value="itemIndex + 1"/>
                    </t>
                </t>
                <t t-set="current" t-value=""/>
                <t t-foreach="currentEmojis" t-as="emoji" t-key="emoji_index">
                    <t t-if="!this.searchTerm() and current !== emoji.category">
                        <t t-set="current" t-value="emoji.category"/>
                        <t t-call="web.EmojiPicker.section" category="current"/>
                    </t>
                    <t t-elif="this.searchTerm()" t-set="categorySortId" t-value="null"/>
                    <t t-call="web.EmojiPicker.emoji"/>
                    <t t-set="itemIndex" t-value="itemIndex + 1"/>
                </t>
            </div>
            <div class="o-EmojiPicker-navbar d-flex flex-shrink-0 w-100 align-items-center justify-content-center overflow-auto px-1 gap-1 border-top" t-att-class="{ 'opacity-0': !this.emojiNavbarRepr() }" t-ref="this.navbarRef">
                <t t-set="currentNavbarPanel" t-value="this.getCurrentNavbarPanel(_recentEmojis)"/>
                <t t-if="currentNavbarPanel">
                    <t t-set="allCategories" t-value="this.getAllCategories(_recentEmojis)"/>
                    <t t-foreach="currentNavbarPanel" t-as="navbarItemId" t-key="navbarItemId">
                        <t t-if="navbarItemId === 'next'" t-call="web.EmojiPicker.tabNext"/>
                        <t t-elif="navbarItemId === 'previous'" t-call="web.EmojiPicker.tabPrev"/>
                        <t t-elif="typeof navbarItemId === 'string' and navbarItemId.startsWith('empty')" t-call="web.EmojiPicker.tabEmpty"/>
                        <t t-else="">
                            <t t-set="category" t-value="allCategories.find(cat =&gt; cat.sortId === navbarItemId)"/>
                            <t t-if="category" t-call="web.EmojiPicker.tab"/>
                        </t>
                    </t>
                </t>
            </div>
        </t>
    </div>
</t>

`);
