registerTemplate("web.FileViewer", `/web/static/src/core/file_viewer/file_viewer.xml`, `<t t-name="web.FileViewer" xml:space="preserve">
        <div class="d-flex justify-content-center" t-att-class="{ 'modal modal-fullscreen': this.props.modal }">
            <div class="o-FileViewer flex-column align-items-center d-flex w-100 h-100" tabindex="0" t-ref="this.autofocusRef" t-on-keydown.stop="(ev) =&gt; this.onKeydown(ev)">
                <div class="o-FileViewer-header position-absolute top-0 d-flex w-100" t-on-click.stop="">
                    <div t-if="this.isViewable" class="d-flex align-items-center ms-4 me-2">
                        <i t-if="this.state.file.isImage" class="oi" data-icon="image" role="img" title="Image"/>
                        <i t-if="this.state.file.isPdf" class="oi oi-filled" data-icon="article" role="img" title="PDF file"/>
                        <i t-if="this.state.file.isText" class="oi oi-filled" data-icon="article" role="img" title="Text file"/>
                        <i t-if="this.state.file.isVideo" class="oi oi-filled" data-icon="videocam" role="img" title="Video"/>
                    </div>
                    <div class="d-flex align-items-center ms-4 overflow-auto">
                        <span class="text-truncate" t-out="this.state.file.name"/>
                    </div>
                    <div class="flex-grow-1"/>
                    <div class="o-FileViewer-download o-FileViewer-headerButton d-flex align-items-center px-3 cursor-pointer" role="button" title="Download" t-on-click.stop="this.onClickDownload">
                        <div class="text-reset d-flex align-items-baseline">
                            <i class="oi oi-fw me-1" data-icon="download" role="img"/>
                            <span>Download</span>
                        </div>
                    </div>
                    <div t-if="this.canUnlink" class="o-FileViewer-headerButton d-flex align-items-center px-3 cursor-pointer" role="button" title="Remove" aria-label="Remove" t-on-click.stop="this.onClickUnlink">
                        <i class="oi oi-fw oi-filled text-danger" data-icon="delete" role="img"/>
                    </div>

                    <div t-on-click.stop="this.close" class="o-FileViewer-headerButton d-flex align-items-center mb-0 px-3 h4 text-reset cursor-pointer" role="button" title="Close (Esc)" aria-label="Close">
                        <i class="oi oi-fw" data-icon="close" role="img"/>
                    </div>
                </div>
                <div t-on-click.stop="this.close" t-on-mousemove="this.onMouseMoveImage" t-on-touchmove.prevent="this.onTouchMoveImage" class="o-FileViewer-main position-absolute top-0 bottom-0 start-0 end-0 align-items-center justify-content-center d-flex" t-att-class="{ 'o_with_img overflow-hidden': this.state.file.isImage }">
                    <div t-if="this.state.file.isImage" class="o-FileViewer-zoomer position-absolute align-items-center justify-content-center d-flex w-100 h-100" t-ref="this.zoomerRef">
                        <div t-if="!this.state.imageLoaded" class="position-absolute">
                            <i class="oi oi-3x oi-fw oi-spin text-white" data-icon="autorenew" role="img" title="Loading"/>
                        </div>
                        <img t-on-click.stop="" t-on-load="this.onImageLoaded" t-on-wheel="this.onWheelImage" t-on-mousedown.stop="this.onMouseDownImage" t-on-mouseup.stop="this.onMouseUpImage" t-on-touchstart="this.onTouchStartImage" t-on-touchend="this.onTouchEndImage" class="o-FileViewer-view o-FileViewer-viewImage mw-100 mh-100" t-att-class="{'transition-base': !this.hasTouch}" t-att-src="this.state.file.defaultSource" t-att-style="this.imageStyle" draggable="false" alt="Viewer" t-ref="this.imageRef"/>
                    </div>
                    <iframe t-if="this.state.file.isPdf" class="o-FileViewer-view w-75 h-100 border-0" t-ref="this.iframeViewerPdfRef" t-att-class="{ 'w-100': this.ui.isSmall }" t-att-src="this.state.file.defaultSource"/>
                    <iframe t-if="this.state.file.isText" class="o-FileViewer-view o-isText o_text w-75 h-100 border-0" t-att-class="{ 'w-100': this.ui.isSmall, 'o-FileViewer-loading': !this.state.isIframeLoaded }" t-att-src="this.state.file.defaultSource" t-on-load="this.onIframeLoaded" loading="lazy" sandbox=""/>
                    <iframe t-if="this.state.file.isUrlYoutube" allow="autoplay; encrypted-media" class="o-FileViewer-view w-75 h-100 border-0" t-att-src="this.state.file.defaultSource" height="315" width="560"/>
                    <video t-if="this.state.file.isVideo" class="o-FileViewer-view w-75 h-75" t-att-class="{ 'w-100 h-100': this.ui.isSmall }" t-on-click.stop="" controls="controls">
                        <source t-att-data-type="this.state.file.mimetype" t-att-src="this.state.file.defaultSource"/>
                    </video>
                    <div t-if="this.state.file.isAudio" t-on-click.stop="" class="o-FileViewer-view w-25 h-25 d-flex flex-column bg-white" t-att-class="{ 'w-100 h-100': this.ui.isSmall }">
                        <div class="d-flex justify-content-center align-items-center flex-grow-1 rounded-3 rounded-bottom-0">
                            <div class="o_image w-50 h-50" role="menuitem" aria-label="Preview" tabindex="-1" data-mimetype="audio/mpeg"/>
                        </div>
                        <audio class="w-100 rounded-0" controls="controls">
                            <source t-att-data-type="this.state.file.mimetype" t-att-src="this.state.file.defaultSource"/>
                        </audio>
                    </div>
                </div>
                <div t-if="this.state.file.isImage" class="o-FileViewer-toolbar border position-absolute d-flex rounded-pill" t-ref="this.imageToolbarRef" role="toolbar">
                    <div class="o-FileViewer-toolbarButton p-3 rounded-pill rounded-end-0" t-on-click.stop="this.zoomIn" title="Zoom In (+)" role="button">
                        <i class="oi oi-fw" data-icon="add" aria-hidden="true"/>
                    </div>
                    <div class="o-FileViewer-toolbarButton p-3 rounded-0" t-att-class="{ 'pe-none text-muted': this.state.scale === 1 }" t-on-click.stop="this.resetZoom" role="button" title="Reset Zoom (0)">
                        <i class="oi oi-fw" data-icon="recenter" aria-hidden="true"/>
                    </div>
                    <div class="o-FileViewer-toolbarButton p-3 rounded-0" t-att-class="{ 'pe-none text-muted': this.state.scale === this.minScale }" t-on-click.stop="this.zoomOut" title="Zoom Out (-)" role="button">
                        <i class="oi oi-fw" data-icon="remove" aria-hidden="true"/>
                    </div>
                    <div class="o-FileViewer-toolbarButton p-3 rounded-0" t-on-click.stop="this.rotate" title="Rotate (r)" role="button">
                        <i class="oi oi-fw" data-icon="redo" aria-hidden="true"/>
                    </div>
                    <div class="o-FileViewer-toolbarButton p-3 rounded-0" t-on-click.stop="this.onClickPrint" title="Print" role="button">
                        <i class="oi oi-fw" data-icon="print" aria-hidden="true"/>
                    </div>
                    <div class="o-FileViewer-download o-FileViewer-toolbarButton p-3 rounded-pill rounded-start-0 cursor-pointer" title="Download" role="button" t-on-click.stop="this.onClickDownload">
                        <i class="oi oi-fw" data-icon="download" aria-hidden="true"/>
                    </div>
                </div>
                <t t-if="this.props.files.length &gt; 1">
                    <div class="o-FileViewer-navigation position-absolute top-0 bottom-0 start-0 align-items-center justify-content-center d-flex my-auto ms-3 rounded-circle bg-dark text-white" t-on-click.stop="this.previous" title="Previous (Left-Arrow)" aria-label="Previous" role="button">
                        <span class="oi" data-icon="chevron_backward" role="img"/>
                    </div>
                    <div class="o-FileViewer-navigation position-absolute top-0 bottom-0 end-0 align-items-center justify-content-center d-flex my-auto me-3 rounded-circle bg-dark text-white" t-on-click.stop="this.next" title="Next (Right-Arrow)" aria-label="Next" role="button">
                        <span class="oi" data-icon="chevron_forward" role="img"/>
                    </div>
                </t>
            </div>
        </div>
    </t>

`);
registerTemplate("web.InstallScopedApp", `/web/static/src/core/install_scoped_app/install_scoped_app.xml`, `<t t-name="web.InstallScopedApp" xml:space="preserve">
        <div class="o_install_scoped_app o_home_menu_background h-100 w-100 d-flex align-items-center justify-content-center user-select-none">
            <button class="btn btn-link m-1 position-absolute start-0 top-0" t-on-click="() =&gt; window.close()">
                <svg xmlns="http://www.w3.org/2000/svg" style="transform:rotate(135deg);" width="28" height="28" viewBox="-7 -7 24 24" preserveAspectRatio="xMinYMin">
                    <path fill="#000" d="M8 8V1a1 1 0 1 1 2 0v8a1 1 0 0 1-1 1H1a1 1 0 1 1 0-2h7z"/>
                </svg>
            </button>
            <i t-if="!this.state.showInstallUI" class="oi oi-spin oi-2x text-primary position-absolute" data-icon="autorenew"/>
            <div t-attf-class="h-100 w-100 d-flex align-items-center justify-content-center flex-column fade {{this.state.showInstallUI ? 'show': ''}}">
                <div class="d-flex align-items-center justify-content-center flex-wrap gap-3 m-4 mw-75 mw-md-50">
                    <img style="height:100px;width:100px;" class="rounded-4 p-4 bg-white shadow" t-att-src="this.state.manifest.icons?.[0]?.src"/>
                    <div class="d-inline-block">
                        <div class="d-flex align-items-center">
                            <h1 class="mb-0" t-out="this.state.manifest.name"/>
                            <Dropdown t-if="this.pwa.isAvailable" menuClass="'p-2'">
                                <button class="btn btn-link oi oi-filled" data-icon="edit"/>
                                <t t-set-slot="content">
                                    <label class="mb-1">Application name</label>
                                    <input class="form-control" t-att-value="this.state.manifest.name" t-on-change="this.onChangeName"/>
                                </t>
                            </Dropdown>
                        </div>
                        <a class="text-primary text-decoration-none" href="https://odoo.com" alt="Odoo" target="_blank">Odoo S.A.</a>
                    </div>
                </div>
                <button t-if="this.pwa.isAvailable" class="btn btn-primary btn-lg rounded-5 shadow py-2 px-3" t-on-click="this.onInstall">Install</button>
                <div t-else="" class="p-2 px-4 overflow-hidden rounded-2 mw-75 bg-info text-white">
                    <t t-if="this.pwa.isSupportedOnBrowser">
                        <span t-if="this.pwa.hasScopeBeenInstalled()">The app seems to be installed on your device</span>
                        <span t-else="">You can install the app from the browser menu</span>
                    </t>
                    <span t-else="">The app cannot be installed with this browser</span>
                </div>
            </div>
        </div>
    </t>
`);
registerTemplate("web._ModelFieldSelector", `/web/static/src/core/model_field_selector/model_field_selector.xml`, `<t t-name="web._ModelFieldSelector" xml:space="preserve">
        <div class="o_model_field_selector d-flex" aria-atomic="true" t-att-class="this.props.readonly ? 'o_read_mode' : 'o_edit_mode o_input'" t-on-click="(ev) =&gt; this.openPopover(ev.currentTarget)">
            <div class="o_model_field_selector_value flex-grow-1 h-100" tabindex="0" t-att-data-tooltip="this.state.displayNames.join(' &gt; ')" data-tooltip-position="top">
                <t t-foreach="this.state.displayNames" t-as="displayName" t-key="displayName_index">
                    <t t-if="!displayName_first">
                        <i class="oi m-1" data-icon="chevron_forward" role="img" aria-label="Followed by" data-tooltip="Followed by"/>
                    </t>
                    <span t-attf-class="o_model_field_selector_chain_part text-truncate d-inline-block align-middle mb-1 #{this.props.readonly ? 'border-0 fw-bolder' : 'px-1'}">
                        <t t-out="displayName"/>
                    </span>
                </t>
            </div>
            <div t-if="!this.props.readonly and this.state.isInvalid" class="o_model_field_selector_controls ms-2" tabindex="0">
                <i class="oi text-warning o_model_field_selector_warning" data-icon="warning" role="alert" aria-label="Invalid field chain" data-tooltip="Invalid field chain"/>
            </div>
            <div t-if="!this.props.readonly and this.props.allowEmpty and this.state.displayNames.length" class="o_model_field_selector_controls ms-2" tabindex="0">
                <i class="oi" data-icon="close" t-on-click.stop="this.clear" aria-label="Clear" data-tooltip="Clear"/>
            </div>
        </div>
    </t>

`);
registerTemplate("web.ModelFieldSelectorPopover", `/web/static/src/core/model_field_selector/model_field_selector_popover.xml`, `<t t-name="web.ModelFieldSelectorPopover" xml:space="preserve">
        <div class="o_model_field_selector_popover d-flex flex-column" tabindex="-1" t-ref="this.rootRef" t-on-keydown="this.onInputKeydown">
            <div class="border-bottom p-2 text-dark fw-bolder">
                <div class="d-flex justify-content-between align-items-center">
                    <t t-if="this.state.page.previousPage">
                        <i class="o_model_field_selector_popover_prev_page btn btn-link oi ms-n2 text-dark" data-icon="arrow_back" data-tooltip="Previous" role="img" aria-label="Previous" t-on-click="() =&gt; this.goToPreviousPage()"/>
                    </t>
                    <div class="o_model_field_selector_popover_title px-2 text-truncate">
                        <t t-out="this.state.page.title"/>
                    </div>
                    <i class="o_model_field_selector_popover_close btn btn-link me-n2 oi text-dark" data-icon="times" data-tooltip="Close" role="img" aria-label="Close" t-on-click="() =&gt; this.props.close()"/>
                </div>
                <t t-if="this.props.showSearchInput">
                    <div class="o_model_field_selector_popover_search mt-1">
                        <input type="text" placeholder="Search..." class="o_input p-1 border rounded-1 bg-view" t-att-value="this.state.page.query" t-on-input="(ev) =&gt; this.debouncedSearchFields(ev.target.value)"/>
                    </div>
                </t>
            </div>
            <div class="o_model_field_selector_popover_body overflow-auto">
                <ul class="o_model_field_selector_popover_page list-unstyled mb-0">
                    <t t-foreach="this.fieldNames" t-as="fieldName" t-key="fieldName">
                        <t t-set="fieldDef" t-value="this.state.page.fieldDefs[fieldName]"/>
                        <li class="o_model_field_selector_popover_item d-flex border-bottom" t-att-class="{ 'active': fieldName === this.state.page.focusedFieldName }" t-att-data-name="fieldName">
                            <button t-attf-class="o_model_field_selector_popover_item_name btn btn-light flex-fill border-0 rounded-0 text-break text-start fw-normal" t-on-click="() =&gt; this.selectField(fieldDef)">
                                <t t-out="fieldDef.string"/>
                                <t t-if="fieldDef.record_name"> (<t t-out="fieldDef.record_name"/>)</t>
                                <div t-if="this.props.isDebugMode" class="o_model_field_selector_popover_item_title text-break text-muted small"><t t-out="fieldName"/> (<t t-out="fieldDef.type"/>)</div>
                            </button>
                            <t t-if="this.canFollowRelationFor(fieldDef)">
                                <t t-set="label">
                                    <t t-if="fieldDef.relation">Relation to follow</t>
                                    <t t-else="">Show options</t>
                                </t>
                                <button class="o_model_field_selector_popover_item_relation btn btn-light border-0 border-start rounded-0" t-att-data-tooltip="label" t-att-aria-label="label" t-on-click.stop="() =&gt; this.followRelation(fieldDef)">
                                    <i class="oi o_model_field_selector_popover_relation_icon" data-icon="chevron_forward" role="img"/>
                                </button>
                            </t>
                        </li>
                    </t>
                </ul>
            </div>
            <div t-if="this.showDebugInput" class="o_model_field_selector_popover_footer border-top py-1 px-2">
                <input type="text" class="o_model_field_selector_debug o_input" t-att-value="this.state.page.path" t-on-change="(ev) =&gt; this.loadNewPath(ev.target.value)" t-on-keydown="this.onDebugInputKeydown" t-on-input="(ev) =&gt; this.props.update(ev.target.value, null, true)"/>
            </div>
        </div>
    </t>

`);
registerTemplate("web.ModelSelector", `/web/static/src/core/model_selector/model_selector.xml`, `<t t-name="web.ModelSelector" xml:space="preserve">
        <div class="o_model_selector">
            <input t-if="this.uiService.isSmall" type="text" class="o_input" readonly="" t-att-id="this.props.id" t-att-value="this.props.value"/>
            <AutoComplete t-else="" id="this.props.id" value="this.props.value || ''" sources="this.sources" placeholder="this.placeholder" autoSelect="this.props.autoSelect" autofocus="this.props.autofocus"/>
            <span class="o_dropdown_button"/>
        </div>
    </t>
`);
registerTemplate("web.Notebook", `/web/static/src/core/notebook/notebook.xml`, `<t t-name="web.Notebook" xml:space="preserve">
        <div t-attf-class="o_notebook d-flex w-100 {{ this.props.orientation === 'horizontal' ? 'horizontal flex-column' : 'vertical flex-row' }} {{ this.props.className }}" t-if="this.state.currentPage">
            <div class="o_notebook_headers" t-att-class="{ 'm-0': this.props.orientation === 'vertical' }">
                <ul t-attf-class="nav nav-tabs {{ this.props.orientation === 'horizontal' ? 'flex-row flex-nowrap' : 'flex-column p-0' }}">
                    <li t-foreach="this.navItems" t-as="navItem" t-key="navItem[0]" class="nav-item flex-nowrap" t-if="navItem[1].isVisible" t-attf-class="{{ navItem[1].isDisabled ? 'disabled' : '' }}">
                        <button class="nav-link" t-att-class="this._getNavItemClasses(navItem)" t-att-name="navItem[1].name" t-on-click="() =&gt; this.activatePage(navItem[0])" role="tab" tabindex="0" data-available-offline="">
                            <i t-if="this.props.icons and this.props.icons[navItem[0]]" class="oi me-2" t-att-data-icon="this.props.icons[navItem[0]]"/>
                            <t t-out="navItem[1].title"/>
                        </button>
                    </li>
                </ul>
            </div>
            <div class="o_notebook_content tab-content">
                <div class="tab-pane active fade" t-ref="this.activePane">
                    <t t-if="this.page" t-component="this.page.Component" t-key="this.state.currentPage" t-props="this.page.props"/>
                    <t t-else="" t-call-slot="{{ this.state.currentPage }}"/>
                </div>
            </div>
        </div>
    </t>

`);
registerTemplate("web.NotificationAlertDialog", `/web/static/src/core/notification_alert_dialog/notification_alert_dialog.xml`, `<t t-name="web.NotificationAlertDialog" xml:space="preserve">
        <PermissionPromptDialog title.translate="Want to stay updated with notifications?" size="'sm'" close="this.props.close">
            <t t-set-slot="illustration">
                <t t-call="web.NotificationAlertDialog.illustrationAnimated"/>
            </t>
            <t t-set-slot="instructions">
                <ol class="ps-3 fs-5 d-flex flex-column gap-2 text-muted mb-2">
                    <li t-out="this.stepOneText"/>
                    <li>Enable notifications.</li>
                </ol>
            </t>
        </PermissionPromptDialog>
    </t>

    `);
