registerTemplate("website_profile.ProfileDialog", `/website_profile/static/src/components/profile_dialog/profile_dialog.xml`, `<t t-name="website_profile.ProfileDialog" xml:space="preserve">
        <Dialog size="'xl'" title="this.title" modalRef="this.modalRef">
            <div class="row">
                <div class="col-12 col-sm-3 mb-3">
                    <div class="card o_card_people">
                        <div class="card-body">
                            <div class="ratio ratio-1x1 w-100 mb-3">
                                <img class="o_wforum_avatar_img object-fit-cover" t-ref="this.profileImgRef" t-attf-src="/web/image/res.users/#{this.user.id}/avatar_128"/>
                            </div>
                            <div class="d-flex justify-content-center gap-1">
                                <FileUploader onUploaded.bind="this.onUploadProfileImg" acceptedFileExtensions="'image/*'">
                                    <t t-set-slot="toggler">
                                        <button href="#" title="Edit" aria-label="Edit" class="btn btn-primary">
                                            <i class="oi oi-filled float-sm-none float-md-start" data-icon="edit"/>
                                        </button>
                                    </t>
                                    <t t-call-slot="default"/>
                                </FileUploader>
                                <button href="#" title="Clear" aria-label="Clear" class="btn border-primary" t-on-click="this.onClearProfileImg">
                                    <i class="oi float-sm-none float-md-end" data-icon="delete"/>
                                </button>
                            </div>
                            <div class="my-3 mb-0 pt-2 border-top" t-if="this.isEditingMyProfile">
                                <label class="text-primary fw-bold" for="website_profile_profile_dialog_user_website_published">Public Profile</label>
                                <input type="checkbox" class="float-end mt8" name="website_published" id="website_profile_profile_dialog_user_website_published" t-model.proxy="this.user.website_published"/>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="col-12 col-sm-9">
                    <div class="row">
                        <div class="mb-3 col-12">
                            <label class="text-primary mb-1 d-block fw-bold" for="website_profile_profile_dialog_user_name">Name</label>
                            <input type="text" t-attf-class="form-control #{this.state.nameHasError ? 'is-invalid': ''}" name="name" id="website_profile_profile_dialog_user_name" required="True" t-model.proxy="this.user.name" t-ref="this.nameRef"/>
                        </div>

                        <div class="mb-3 col-6">
                            <label class="mb-1 text-primary fw-bold" for="website_profile_profile_dialog_user_website">Website</label>
                            <input type="text" class="form-control" name="website" id="website_profile_profile_dialog_user_website" t-model.proxy="this.user.website"/>
                        </div>
                        <div class="mb-3 col-6">
                            <label class="mb-1 text-primary fw-bold" for="website_profile_profile_dialog_user_email">Email</label>
                            <input type="email" t-attf-class="form-control #{this.state.emailHasError ? 'is-invalid': ''}" name="email" id="website_profile_profile_dialog_user_email" required="True" t-model.proxy="this.user.email"/>
                        </div>
                        <div class="mb-3 col-6">
                            <label class="mb-1 text-primary fw-bold" for="website_profile_profile_dialog_user_city">City</label>
                            <input type="text" class="form-control" name="city" id="website_profile_profile_dialog_user_city" t-model.proxy="this.user.city"/>
                        </div>
                        <div class="mb-3 col-6">
                            <label class="mb-1 text-primary fw-bold" for="website_profile_profile_dialog_user_country">Country</label>
                            <div>
                                <select name="country" class="form-control" id="website_profile_profile_dialog_user_country" t-model.proxy="this.user.country_id" t-att-disabled="!this.props.canEditCountry">
                                    <option>Country...</option>
                                    <option t-foreach="this.countries" t-as="country" t-key="country.id" t-att-value="country.id" t-out="country.name"/>
                                </select>
                                <p t-if="this.props.canEditCountry === false" class="form-text text-muted">Changing the country is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.</p>
                            </div>
                        </div>
                        <div class="mb-3 col-12">
                            <label class="mb-1 text-primary fw-bold">Biography</label>
                            <Wysiwyg config="this.descriptionWysiwygConfig" t-key="this.description" onLoad.bind="this.onWebsiteDescriptionEditorLoad"/>
                        </div>
                    </div>
                </div>
            </div>
            <t t-set-slot="footer">
                <button class="btn btn-primary" t-on-click="this.onConfirm" data-hotkey="q" t-att-disabled="this.state.isProcessing or this.state.hasError">Update</button>
                <button class="btn btn-secondary" t-on-click="this.props.close" data-hotkey="x" t-att-disabled="this.state.isProcessing">Discard</button>
              </t>
        </Dialog>
    </t>

`);
registerTemplate("html_editor.Wysiwyg", `/html_editor/static/src/wysiwyg.xml`, `<t t-name="html_editor.Wysiwyg" xml:space="preserve">
        <div class="o-wysiwyg d-flex flex-column p-0" t-att-class="this.props.class" t-att-style="this.props.style">
            <LocalOverlayContainer localOverlay="this.overlayRef" identifier="this.localOverlayContainerKey"/>
            <div class="flex-grow-1" t-att-class="{'overflow-auto': !this.props.iframe}">
                <t t-if="this.props.iframe">
                    <iframe t-ref="this.contentRef" class="w-100 h-100" t-att-data-class="this.props.contentClass" t-on-focusout="this.props.onBlur"/>
                </t>
                <t t-else="">
                    <div t-att-class="this.props.contentClass" t-ref="this.contentRef" t-on-focusout="this.props.onBlur" contenteditable="true"/>
                </t>
            </div>
        </div>
    </t>
`);
registerTemplate("html_editor.ColorPicker", `/html_editor/static/src/components/color_picker/color_picker.xml`, `<t t-name="html_editor.ColorPicker" xml:space="preserve">
    <div t-attf-class="o_font_color_selector user-select-none {{this.props.className}}" t-on-pointerdown.stop="() =&gt; {}" data-prevent-closing-overlay="true" t-ref="this.rootRef" t-on-mouseenter="this.onMouseEnter">
        <div class="px-1 mb-1 pt-2 d-flex">
            <t t-if="this.isMobileOS">
                <Dropdown>
                    <button class="btn btn-light d-flex justify-content-between w-100 border border-dark">
                        <span class="px-1" t-out="this.state.activeTab"/>
                        <i class="oi ms-2" data-icon="arrow_drop_down"/>
                    </button>
                    <t t-set-slot="content">
                        <t t-foreach="this.tabs" t-as="item" t-key="item.id">
                            <DropdownItem onSelected="() =&gt; this.setTab(item.id)">
                                    <t t-out="item.name"/>
                            </DropdownItem>
                        </t>
                    </t>
                </Dropdown>
            </t>
            <t t-else="">
                <t t-foreach="this.tabs" t-as="tab" t-key="tab.id">
                    <button t-attf-class="btn btn-sm text-truncate btn-tab me-1 #{tab.id}-tab #{ this.isDarkTheme ? 'btn-secondary' : 'btn-light'} #{this.state.activeTab === tab.id ? 'active' : ''}" t-on-click="() =&gt; this.setTab(tab.id)">
                        <t t-out="tab.name"/>
                    </button>
                </t>
            </t>
            <div class="flex-grow-1"/>
            <button t-attf-class="btn btn-sm oi oi-filled o_color_picker_reset #{ this.isDarkTheme ? 'btn-secondary' : 'btn-light'}" data-icon="delete" title="Reset" t-on-click="this.onColorApply" t-on-mouseover="this.onColorHover" t-on-mouseout="this.onColorHoverOut" t-on-focusin="this.onColorFocusin" t-on-focusout="this.onColorFocusout"/>
        </div>
        <t t-set="activeTab" t-value="this.tabs.find((tab) =&gt; this.state.activeTab === tab.id)"/>
        <t t-component="activeTab.component" t-props="{             applyColor: this.applyColor.bind(this),             onColorClick: this.onColorApply.bind(this),             onColorPointerOver: this.onColorHover.bind(this),             onColorPointerOut: this.onColorHoverOut.bind(this),             onColorPointerLeave: this.applyColorResetPreview.bind(this),             onFocusin: this.onColorFocusin.bind(this),             onFocusout: this.onColorFocusout.bind(this),             colorPickerNavigation: this.colorPickerNavigation.bind(this),             onColorPreview: this.onColorPreview.bind(this),             setOnCloseCallback: this.props.setOnCloseCallback.bind(this),             setOperationCallbacks: this.setOperationCallbacks.bind(this),             editColorCombination: this.props.editColorCombination,             close: this.props.close,             selectedColorCombination: this.props.state.selectedColorCombination,             defaultOpacity: this.props.defaultOpacity,             noTransparency: this.props.noTransparency,             defaultThemeColorVars: this.DEFAULT_THEME_COLOR_VARS,             defaultColorSet: this.defaultColorSet,             cssVarColorPrefix: this.props.cssVarColorPrefix,             defaultColors: this.DEFAULT_COLORS,             getUsedCustomColors: this.props.getUsedCustomColors,             grayscales: this.grayscales,             currentCustomColor: this.state.currentCustomColor,             currentColorPreview: this.state.currentColorPreview,             selectedColor: this.props.state.selectedColor,         }"/>
    </div>
</t>

`);
registerTemplate("html_editor.CustomColorPicker", `/html_editor/static/src/components/color_picker/custom_color_picker/custom_color_picker.xml`, `<t t-name="html_editor.CustomColorPicker" xml:space="preserve">
    <div class="o_colorpicker_widget" t-ref="this.elRef" t-on-click="this.onClick" t-on-keydown="this.onKeydown">
        <div class="d-flex justify-content-between align-items-stretch mb-2">
            <div t-ref="this.colorPickerAreaRef" role="application" aria-label="Saturation and brightness color picker." aria-roledescription="Use up and down arrow keys to adapt the brightness. Use left and right arrow keys to adapt the saturation. Press the Control or Command key at the same time to have finer control." aria-activedescendant="picker_pointer" class="o_color_pick_area position-relative w-75" t-att-style="this.props.noTransparency ? 'width: 89%;' : None" t-on-pointerdown="this.onPointerDownPicker">
                <div t-ref="this.colorPickerPointerRef" id="picker_pointer" class="o_picker_pointer rounded-circle p-1 position-absolute" tabindex="0" t-on-keydown="this.onPickerKeydown"/>
            </div>
            <div t-ref="this.colorSliderRef" class="o_color_slider position-relative" t-on-pointerdown="this.onPointerDownSlider">
                <div t-ref="this.colorSliderPointerRef" class="o_slider_pointer" tabindex="0" t-on-keydown="this.onSliderKeydown" role="slider" aria-label="Hue" aria-orientation="vertical" aria-valuemin="0" aria-valuemax="360"/>
            </div>
            <div t-ref="this.opacitySliderRef" class="o_opacity_slider position-relative" t-if="!this.props.noTransparency" t-on-pointerdown="this.onPointerDownOpacitySlider">
                <div t-ref="this.opacitySliderPointerRef" class="o_opacity_pointer" tabindex="0" t-on-keydown="this.onOpacitySliderKeydown" role="slider" aria-label="Opacity" aria-orientation="vertical" aria-valuemin="0" aria-valuemax="100"/>
            </div>
        </div>
        <div class="o_color_picker_inputs d-flex mb-2">
            <div class="o_hex_div px-1 d-flex align-items-center">
                <IframeInput value="this.hexDisplay.value" inputAttrs="{ name: 'hex_input' }" iframeClass="'o_hex_iframe'" inputStyle="'border: 1px solid; background-color: transparent; font-family: monospace; font-size: 11px;'" onClick.bind="this.onHexInputClick" onInput.bind="this.onHexColorInput" onKeydown.bind="this.onKeydown"/>
                <label class="flex-grow-0 ms-1">hex</label>
            </div>
            <button t-if="window.EyeDropper" class="btn btn-sm p-0 px-1" title="Pick a color from the screen" t-on-click="this.pickColor">
                <i class="oi" data-icon="colorize"/>
            </button>
        </div>
    </div>
</t>

`);
registerTemplate("html_editor.GradientPicker", `/html_editor/static/src/components/color_picker/gradient_picker/gradient_picker.xml`, `<t t-name="html_editor.GradientPicker" xml:space="preserve">
        <div class="d-flex flex-column" t-on-keydown="this.onKeydown">

            <div class="align-items-center d-flex justify-content-between my-3 o_type_row">
                Type
                <t t-if="this.isMobileOS">
                    <Dropdown>
                        <button class="btn btn-light d-flex justify-content-between w-100 ms-2 border border-dark rounded-0">
                            <span class="px-1" t-out="this.state.type"/>
                            <i class="oi ms-2" data-icon="arrow_drop_down"/>
                        </button>
                        <t t-set-slot="content">
                            <DropdownItem onSelected="() =&gt; this.selectType('linear')">
                                Linear
                            </DropdownItem>
                            <DropdownItem onSelected="() =&gt; this.selectType('radial')">
                                Radial
                            </DropdownItem>
                            <DropdownItem onSelected="() =&gt; this.selectType('conic')">
                                Conic
                            </DropdownItem>
                        </t>
                    </Dropdown>
                </t>
                <t t-else="">
                    <span class="d-flex justify-content-between">
                        <button t-attf-class="btn btn-sm btn-light {{ this.state.type === 'linear' ? 'active' : ''}}" t-on-click="() =&gt; this.selectType('linear')"> Linear </button>
                        <button t-attf-class="btn btn-sm btn-light {{ this.state.type === 'radial' ? 'active' : ''}}" t-on-click="() =&gt; this.selectType('radial')"> Radial </button>
                        <button t-attf-class="btn btn-sm btn-light {{ this.state.type === 'conic' ? 'active' : ''}}" t-on-click="() =&gt; this.selectType('conic')"> Conic </button>
                    </span>
                </t>
            </div>

            <div t-if="this.state.type === 'radial'">
                <div class="d-flex flex-column gap-1 mb-1 me-n1 o_radial_size_row">
                    <div class="d-flex align-items-center justify-content-between" t-on-mouseover="this.props.onColorPointerOver" t-on-mouseout="this.props.onColorPointerOut">
                        <div style="margin-right: auto;">
                            Size
                        </div>
                        <button t-on-click="() =&gt; this.onSizeChange('closest-side')" t-att-data-color="this.getRadialGradient('closest-side')" t-attf-class="btn btn-light p-0 {{ this.state.size === 'closest-side' ? \`active\` : ''}}" title="Extend to the closest side">
                            <img src="/html_editor/static/src/img/gradient-closest-side.svg"/>
                        </button>
                        <button t-on-click="() =&gt; this.onSizeChange('closest-corner')" t-att-data-color="this.getRadialGradient('closest-corner')" t-attf-class="btn btn-light p-0 {{ this.state.size === 'closest-corner' ? \`active\` : ''}}" title="Extend to the closest corner">
                            <img src="/html_editor/static/src/img/gradient-closest-corner.svg"/>
                        </button>
                        <button t-on-click="() =&gt; this.onSizeChange('farthest-side')" t-att-data-color="this.getRadialGradient('farthest-side')" t-attf-class="btn btn-light p-0 {{ this.state.size === 'farthest-side' ? \`active\` : ''}}" title="Extend to the farthest side">
                            <img src="/html_editor/static/src/img/gradient-farthest-side.svg"/>
                        </button>
                        <button t-on-click="() =&gt; this.onSizeChange('farthest-corner')" t-att-data-color="this.getRadialGradient('farthest-corner')" t-attf-class="btn btn-light p-0 {{ this.state.size === 'farthest-corner' ? \`active\`: ''}}" title="Extend to the farthest corner">
                            <img src="/html_editor/static/src/img/gradient-farthest-corner.svg"/>
                        </button>
                    </div>
                </div>
            </div>
            <div t-if="this.state.type === 'linear' or this.state.type === 'conic'">
                <div class="d-flex align-items-center justify-content-between mb-1">
                    Angle
                    <span class="d-flex justify-content-between align-items-center">
                        <div class="d-flex justify-content-center align-items-center my-auto me-2 position-relative gradient-angle-knob" t-ref="this.knobRef" t-attf-style="--angle: #{this.state.angle - 90}deg;" t-on-mousedown="this.onKnobMouseDown">
                            <div class="position-absolute gradient-angle-thumb"/>
                        </div>
                        <div class="o_color_gradient_input d-flex align-items-center">
                            <IframeInput value="this.state.angle" inputAttrs="{ name: 'angle_input', type: 'number', min: -360, max: 360 }" iframeClass="'o_angle_iframe'" inputStyle="'background-color: transparent; font-family: monospace; font-size: 12px;'" onInput.bind="this.onAngleChange"/>
                            <span>deg</span>
                        </div>
                    </span>
                </div>
            </div>
            <div t-if="this.state.type === 'radial' or this.state.type === 'conic'">
                <div class="d-flex flex-column gap-1 mb-1">
                    <div class="d-flex align-items-center justify-content-between">
                        Position X
                        <div class="d-flex">
                            <span class="o_color_gradient_input">
                                <IframeInput value="this.positions['x']" inputAttrs="{ name: 'position_x_input', type: 'number', min: -100, max: 200 }" iframeClass="'o_position_x_iframe'" inputStyle="'background-color: transparent; font-family: monospace; font-size: 12px;'" onChange.bind="(ev) =&gt; this.onPositionChange('x', ev)"/>
                                <span>%</span>
                            </span>
                        </div>
                    </div>
                    <div class="d-flex align-items-center justify-content-between">
                        Position Y
                        <div class="d-flex">
                            <span class="o_color_gradient_input">
                                <IframeInput value="this.positions['y']" inputAttrs="{ name: 'position_y_input', type: 'number', min: -100, max: 200 }" iframeClass="'o_position_y_iframe'" inputStyle="'background-color: transparent; font-family: monospace; font-size: 12px;'" onChange.bind="(ev) =&gt; this.onPositionChange('y', ev)"/>
                                <span>%</span>
                            </span>

                        </div>
                    </div>
                </div>
            </div>



            <div class="custom-gradient-configurator mt-3">
                <div class="mb-1 d-flex justify-content-between align-items-center">
                    Colors
                    <div class="d-flex align-items-center">
                        Repeating
                        <CheckBox className="'ms-1 d-flex align-items-center justify-content-center o_field_boolean o_boolean_toggle form-switch'" onChange="this.onToggleRepeatingBound" value="this.state.repeating"/>
                    </div>
                </div>
                <div class="gradient-checkers"/>
                <div class="gradient-preview" t-attf-style="background-image: #{this.cssGradients.preview};" t-on-click="this.onGradientPreviewClick">
                </div>
                <style><t t-out="this.cssGradients.sliderThumbStyle"/></style>
                <div class="gradient-colors">
                    <div t-foreach="this.colors" t-as="color" t-key="color_index">
                        <input type="range" min="0" max="100" t-att-value="color.percentage" t-att-class="{'active': this.state.currentColorIndex === color_index}" t-attf-name="custom gradient percentage color #{color_index+1}" t-on-change="(ev) =&gt; this.onColorPercentageChange(color_index, ev)" t-on-pointerdown="() =&gt; this.state.currentColorIndex = color_index"/>
                    </div>
                    <div class="position-relative text-white fw-bolder color-percentage pe-none d-flex justify-content-center" t-out="this.colors[this.state.currentColorIndex].percentage" t-attf-style="left: calc(#{this.colors[this.state.currentColorIndex].percentage}% - #{15 + 0.08*this.colors[this.state.currentColorIndex].percentage}px);"/>
                </div>
                <div class="gradient-color-bin position-relative">
                    <t t-if="this.colors.length &gt; 2">
                        <a t-on-click="() =&gt; this.removeColor(this.state.currentColorIndex)" t-attf-style="left: #{this.colors[this.state.currentColorIndex].percentage}%" type="button" class="btn btn-sm btn-light position-absolute">
                           <i class="oi oi-fw oi-filled" data-icon="delete" role="img"/>
                        </a>
                    </t>
                </div>
            </div>

            <ColorPicker onColorSelect.bind="this.onColorChange" onColorPreview.bind="this.onColorPreview" defaultColor="this.currentColorHex" selectedColor="this.currentColorHex" noTransparency="this.props.noTransparency"/>
        </div>
    </t>
`);
registerTemplate("html_editor.ColorPickerCustomTab", `/html_editor/static/src/components/color_picker/tabs/custom/color_picker_custom_tab.xml`, `<t t-name="html_editor.ColorPickerCustomTab" xml:space="preserve">
    <div class="d-flex flex-column align-items-start p-2 pb-0" t-on-keydown="this.props.colorPickerNavigation">
        <div class="o_colorpicker_section" t-on-click="this.props.onColorClick" t-on-mouseover="this.props.onColorPointerOver" t-on-mouseout="this.props.onColorPointerOut" t-on-focusin="this.props.onFocusin" t-on-focusout="this.props.onColorPointerOut">
            <t t-foreach="this.usedCustomColors" t-as="color" t-key="color_index">
                <button t-if="color.toLowerCase() !== this.props.currentCustomColor?.toLowerCase()" class="o_color_button o_color_picker_button btn p-0" t-att-data-color="color" t-attf-style="background-color: {{color}}"/>
            </t>
            <button t-if="!this.props.defaultColorSet and this.isValidCustomColor(this.props.currentCustomColor)" class="o_color_button o_color_picker_button btn p-0" t-att-class="{'selected': this.props.defaultColorSet === false and !this.props.currentColorPreview}" t-attf-style="background-color: {{this.props.currentCustomColor}}" t-att-data-color="this.props.currentCustomColor"/>
            <button t-if="!!this.props.currentColorPreview" class="o_color_button o_color_picker_button btn p-0" t-att-class="{ 'selected': !!this.props.currentColorPreview }" t-attf-style="background-color: {{this.props.currentColorPreview}}" t-att-data-color="this.props.currentColorPreview"/>
        </div>
        <t t-foreach="Object.values(this.props.grayscales)" t-as="grayscaleColors" t-key="grayscaleColors">
            <div class="o_colorpicker_section" t-on-click="this.props.onColorClick" t-on-mouseover="this.props.onColorPointerOver" t-on-mouseout="this.props.onColorPointerOut" t-on-focusin="this.props.onFocusin" t-on-focusout="this.props.onColorPointerOut">
                <t t-foreach="grayscaleColors" t-as="color" t-key="color">
                    <button t-att-data-color="color" class="o_color_button o_color_picker_button btn p-0" t-att-class="{'selected': color === this.props.defaultColorSet and !this.props.currentColorPreview}" t-attf-style="background-color: var(--{{this.props.cssVarColorPrefix+color}})"/>
                </t>
            </div>
        </t>
        <CustomColorPicker selectedColor="this.props.currentCustomColor" setOnCloseCallback.bind="this.props.setOnCloseCallback" setOperationCallbacks.bind="this.props.setOperationCallbacks" onColorSelect.bind="(color) =&gt; this.props.applyColor(color.hex)" onColorPreview.bind="this.props.onColorPreview" noTransparency="this.props.noTransparency" defaultOpacity="this.props.defaultOpacity"/>
    </div>
</t>
`);
registerTemplate("html_editor.ColorPickerGradientTab", `/html_editor/static/src/components/color_picker/tabs/gradient/color_picker_gradient_tab.xml`, `<t t-name="html_editor.ColorPickerGradientTab" xml:space="preserve">
    <t t-set="currentGradient" t-value="this.getCurrentGradientColor()"/>
    <div class="o_colorpicker_sections p-2 d-grid gap-1" style="grid-template-columns: 1fr 1fr;" t-on-click="this.props.onColorClick" t-on-mouseover="this.props.onColorPointerOver" t-on-mouseout="this.props.onColorPointerOut" t-on-focusin="this.props.onFocusin" t-on-focusout="this.props.onFocusout">
        <t t-set="gradientsWithOpacity" t-value="this.DEFAULT_GRADIENT_COLORS.map((gradient) =&gt; this.applyOpacityToGradient(gradient, this.props.defaultOpacity))"/>
        <t t-foreach="gradientsWithOpacity" t-as="gradient" t-key="gradient">
            <button class="w-100 m-0 o_color_button o_color_picker_button o_gradient_color_button btn p-0" t-att-class="{'selected': currentGradient?.includes(gradient)}" t-attf-style="background-image: #{gradient};" t-att-data-color="gradient"/>
        </t>
    </div>
    <div class="px-2">
        <button t-ref="this.customGradientButton" t-attf-style="{{ currentGradient ? \`background-image: \${currentGradient}\` : '' }};" class="w-50 btn mb-2 o_custom_gradient_button o_color_picker_button" t-att-class="{'selected': currentGradient and !gradientsWithOpacity.includes(currentGradient)}" t-att-data-color="currentGradient" t-on-click="this.toggleGradientPicker" title="Define a custom gradient">
            Custom
        </button>
        <GradientPicker t-if="this.state.showGradientPicker" onGradientChange.bind="this.props.applyColor" onGradientPreview.bind="this.props.onColorPreview" setOnCloseCallback.bind="this.props.setOnCloseCallback" setOperationCallbacks.bind="this.props.setOperationCallbacks" selectedGradient="this.getCurrentGradientColor()" onColorPointerOver.bind="this.props.onColorPointerOver" onColorPointerOut.bind="this.props.onColorPointerOut" noTransparency="this.props.noTransparency"/>
    </div>
</t>
`);
registerTemplate("html_editor.ColorPickerSolidTab", `/html_editor/static/src/components/color_picker/tabs/solid/color_picker_solid_tab.xml`, `<t t-name="html_editor.ColorPickerSolidTab" xml:space="preserve">
    <div class="d-flex flex-column align-items-center p-1 pb-2" t-on-click="this.props.onColorClick" t-on-mouseover="this.props.onColorPointerOver" t-on-mouseout="this.props.onColorPointerOut" t-on-focusin="this.props.onFocusin" t-on-focusout="this.props.onFocusout" t-ref="this.solidTabRef" t-on-keydown="this.props.colorPickerNavigation">
        <div class="o_colorpicker_section">
            <t t-foreach="this.props.defaultThemeColorVars" t-as="color" t-key="color">
                <button t-att-data-color="color" t-att-class="{'selected': color === this.props.defaultColorSet}" t-att-style="\`background-color: var(--\${this.props.cssVarColorPrefix + color})\` + (color_index === 3 ? '; grid-column: 5' : '')" class="btn p-0 o_color_button o_color_picker_button"/>
            </t>
        </div>

        <div class="o_color_section">
            <t t-foreach="this.props.defaultColors" t-as="line" t-key="line_index">
                <t t-foreach="line" t-as="color" t-key="color_index">
                    <button class="o_color_button o_color_picker_button btn p-0" t-att-class="{'selected': color === this.props.currentCustomColor?.toUpperCase() and !this.props.defaultColorSet}" t-att-data-color="color" t-attf-style="background-color: {{color}}"/>
                </t>
            </t>
        </div>
    </div>
</t>
`);
registerTemplate("html_editor.HistoryDialog", `/html_editor/static/src/components/history_dialog/history_dialog.xml`, `<t t-name="html_editor.HistoryDialog" xml:space="preserve">
        <Dialog size="this.state.size" title="this.title" bodyClass="'p-0'" contentClass="'html-history-dialog-container h-100'" onExpand="this.toggleFullscreen" t-on-close="this.props.close" t-on-cancel="this.props.close" t-on-confirm="this._onRestoreRevisionClick" t-on-after-render="this._onAfterRender">
            <div class="d-flex flex-column h-100 overflow-hidden">
                <ul class="nav nav-tabs d-md-none flex-shrink-0" role="tablist">
                    <li class="nav-item flex-grow-1">
                        <a href="#" id="tab-revisions" class="nav-link position-relative text-center fw-bold" t-att-class="{'active': this.state.mobileActiveTab === 'revisions'}" t-on-click.prevent="() =&gt; this.setMobileTab('revisions')" role="tab" aria-controls="revisions-panel" t-att-aria-selected="this.state.mobileActiveTab === 'revisions' ? 'true' : 'false'">
                            <i class="oi me-1" data-icon="format_list_bulleted" role="img" aria-hidden="true"/>Revisions
                        </a>
                    </li>
                    <li class="nav-item flex-grow-1">
                        <a href="#" id="tab-preview" class="nav-link position-relative text-center fw-bold" t-att-class="{'active': this.state.mobileActiveTab === 'content'}" t-on-click.prevent="() =&gt; this.setMobileTab('content')" role="tab" aria-controls="content-panel" t-att-aria-selected="this.state.mobileActiveTab === 'content' ? 'true' : 'false'">
                            <i class="oi me-1" data-icon="visibility" role="img" aria-hidden="true"/>Preview
                        </a>
                    </li>
                </ul>

                <div class="html-history-dialog position-relative d-flex flex-column flex-md-row h-100" t-attf-class="{{this.state.isLoading ? 'html-history-loading' : 'html-history-loaded'}}">
                    <div id="revisions-panel" class="o_revision_panel h-100 p-3 border-end overflow-auto d-md-flex flex-md-shrink-0" t-att-class="{'d-none': !this.isMobileActiveTab('revisions')}" role="region" aria-labelledby="tab-revisions">
                        <t t-if="!this.state.revisionsData.length">
                            <div class="text-center w-100 pb-2 pt-0 px-0 fw-bolder">No history</div>
                        </t>

                        <ul t-else="" class="list-group w-100" role="listbox" t-ref="this.listboxRef">
                            <t t-foreach="this.state.revisionsData" t-as="rev" t-key="rev.revision_id">
                                <li t-att-data-revision-id="rev.revision_id" t-attf-title="Submitted by #{rev.create_user_name} on #{this.getRevisionFullDate(rev)}" class="o_revision_panel_item list-group-item rounded-2 mb-2 px-2 py-1 border-1 cursor-pointer user-select-none" t-att-class="this.getRevisionClasses(rev)" t-on-click="() =&gt; this.updateCurrentRevision(rev.revision_id)" t-on-keydown="(ev) =&gt; this.onRevisionKeydown(rev.revision_id, ev)" t-att-aria-selected="this.isRevisionSelected(rev) ? 'true' : 'false'" role="option" tabindex="0">
                                    <div class="revision-item-content d-flex justify-content-between align-items-center gap-3">
                                        <div class="revision-info lh-sm">
                                            <time class="revision-date fw-bold d-block" t-att-datetime="rev.create_date">
                                                <t t-out="this.getRevisionDate(rev)"/>
                                            </time>
                                            <div class="revision-author text-muted text-truncate">
                                                <small>by <t t-out="rev.create_user_name"/></small>
                                            </div>
                                        </div>
                                        <div class="o_avatar">
                                            <img class="rounded" t-att-src="this.getRevisionAuthorAvatar(rev)" t-att-alt="rev.create_user_name + ' avatar'"/>
                                        </div>
                                    </div>
                                </li>
                            </t>
                        </ul>
                    </div>
                    <div id="content-panel" class="history-container d-md-flex flex-column flex-grow-1 min-w-0 overflow-hidden" t-att-class="{'d-none': !this.isMobileActiveTab('content')}" role="region" aria-labelledby="tab-preview">
                        <div class="history-view-top-bar d-flex gap-3 justify-content-between align-items-center px-3 border-bottom bg-view">
                            <div class="form-check form-switch">
                                <input class="form-check-input" type="checkbox" role="switch" id="compare-switch" t-att-checked="this.state.currentView === 'comparison'" t-on-change="this.toggleComparison" aria-label="Toggle comparison view"/>
                                <label class="form-check-label fw-medium" for="compare-switch">
                                    Show comparison
                                </label>
                            </div>
                            <div t-if="this.debugMode.isActive() and this.state.currentView === 'comparison'" class="btn-group" role="group" aria-label="Diff view mode">
                                <input type="radio" class="btn-check" name="diff-mode" id="unified-view-btn" t-on-click="this.setComparisonUnified" t-att-checked="!this.state.isComparisonSplit"/>
                                <label class="btn btn-secondary" for="unified-view-btn">Unified</label>
                                <input type="radio" class="btn-check" name="diff-mode" id="split-view-btn" t-on-click="this.setComparisonSplit" t-att-checked="this.state.isComparisonSplit"/>
                                <label class="btn btn-secondary" for="split-view-btn">Split</label>
                            </div>
                        </div>
                        <div class="history-info-bar flex-shrink-0">
                            <div class="alert alert-light py-2 mb-0 rounded-0 border-0" role="status" aria-live="polite">
                                <small>
                                    <i class="oi me-1" data-icon="info" role="img" aria-hidden="true"/>
                                    <t t-if="this.state.currentView === 'content'">
                                        Showing <strong t-out="this.currentRevision.create_user_name"/>'s description from <strong t-out="this.getRevisionFullDate(this.currentRevision)"/>
                                    </t>
                                    <t t-else="">
                                        Comparing current description with <strong t-out="this.currentRevision.create_user_name"/>'s version from <strong t-out="this.getRevisionFullDate(this.currentRevision)"/>
                                    </t>
                                </small>
                            </div>
                        </div>
                        <div t-attf-class="history-content-view d-flex flex-column flex-grow-1 pt-0 #{this.state.currentView !== 'content' ? 'd-none' : ''}">
                            <div class="history-view-inner flex-grow-1 p-3 overflow-auto" t-att-aria-busy="this.state.isLoading ? 'true' : 'false'">
                                <t t-if="this.state.isLoading">
                                    <t t-call="html_editor.HistoryDialog.LoadingSpinner"/>
                                </t>
                                <t t-elif="this.state.revisionContent?.length">
                                    <HtmlViewer config="this.getConfig('revisionContent')"/>
                                </t>
                                <t t-else="" t-out="this.props.noContentHelper"/>
                            </div>
                        </div>
                        <div t-attf-class="history-comparison-view d-flex flex-column flex-grow-1 pt-0 #{this.state.currentView !== 'comparison' ? 'd-none' : ''}">
                            <div class="history-view-inner flex-grow-1 p-3 overflow-auto" t-att-aria-busy="this.state.isLoading ? 'true' : 'false'">
                                <t t-if="this.state.isLoading">
                                    <t t-call="html_editor.HistoryDialog.LoadingSpinner"/>
                                </t>
                                <t t-elif="this.state.revisionComparison?.length">
                                    <div t-attf-class="history-comparison-split position-relative h-100 #{!this.state.isComparisonSplit ? 'd-none' : ''}">
                                        <HtmlViewer config="this.getConfig('revisionComparisonSplit')"/>
                                    </div>
                                    <div t-attf-class="history-comparison-unified #{this.state.isComparisonSplit ? 'd-none' : ''}">
                                        <HtmlViewer config="this.getConfig('revisionComparison')"/>
                                    </div>
                                </t>
                                <t t-else="">
                                    <span class="text-muted fst-italic">This is the current version, nothing to compare.</span>
                                </t>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <t t-set-slot="footer">
                <button class="btn btn-primary" t-on-click="this._onRestoreRevisionClick" t-att-disabled="this.state.isLoading || this.state.revisionId === -1">Restore history</button>
                <button class="btn btn-secondary" t-on-click="this.props.close">Discard</button>
            </t>
        </Dialog>
    </t>

    `);
registerTemplate("html_editor.HistoryDialog.LoadingSpinner", `/html_editor/static/src/components/history_dialog/history_dialog.xml`, `<t t-name="html_editor.HistoryDialog.LoadingSpinner" xml:space="preserve">
        <div class="d-flex flex-column justify-content-center align-items-center">
            <img src="/web/static/img/spin.svg" alt="Loading..." class="loading-spinner me-2 opacity-50"/>
            <p class="m-0 text-muted loading-text">
                <em>Loading...</em>
            </p>
        </div>
    </t>
`);
registerTemplate("html_editor.IframeInput", `/html_editor/static/src/components/iframe_input/iframe_input.xml`, `<t t-name="html_editor.IframeInput" xml:space="preserve">
        <iframe t-ref="this.iframeRef" t-att-class="this.props.iframeClass"/>
    </t>
`);
registerTemplate("html_editor.SuggestionList", `/html_editor/static/src/components/suggestion/suggestion_list.xml`, `<t t-name="html_editor.SuggestionList" xml:space="preserve">
        <div class="o-we-SuggestionList user-select-none" t-ref="this.suggestionListRef">
            <t t-foreach="this.props.state.list" t-as="item" t-key="item.value">
                <div class="d-flex align-items-center py-1 px-2 w-100 cursor-pointer o-navigable" t-on-click.stop="() =&gt; this.onClick(item)">
                    <strong class="px-2 fs-3" t-out="item.value"/>
                    <em class="text-600 text-truncate" t-out="item.label"/>
                </div>
            </t>
        </div>
    </t>
`);
registerTemplate("html_editor.AlignSelector", `/html_editor/static/src/main/align/align_selector.xml`, `<t t-name="html_editor.AlignSelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o-we-toolbar-dropdown'" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.alignSelector" class="btn btn-light" t-att-title="this.props.title" name="text_align">
                <span class="px-1 d-flex align-items-center">
                    <i class="oi" t-att-data-icon="\`format_align_\${this.state.displayName}\`"/>
                </span>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.items" t-as="item" t-key="item_index">
                        <DropdownItem tag="'button'" attrs="{ title: item.description, 'data-icon': \`format_align_\${item.icon}\` }" class="{['dropdown-item_active_noarrow btn btn-light oi']: true, active: item.icon === this.state.displayName }" t-on-pointerdown.prevent="() =&gt; {}" onSelected="() =&gt; this.onSelected(item)"/>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.ColorSelector", `/html_editor/static/src/main/font/color_selector.xml`, `<t t-name="html_editor.ColorSelector" xml:space="preserve">
    <button t-ref="this.colorSelectorBtn" class="btn btn-light" t-attf-class="o-select-color-{{this.props.type}} {{this.colorSelectorState.isOpen ? 'active' : ''}}" t-att-title="this.props.title" t-att-disabled="this.props.isDisabled">
        <t t-if="this.props.type === 'foreground'">
            <i class="oi oi-fw py-1" data-icon="A" t-attf-style="--icon-font-family: Arial, sans-serif; {{this.getSelectedColorStyle()}}"/>
        </t>
        <t t-elif="this.props.type === 'custom'">
            <i class="oi oi-fw py-1" t-att-data-icon="this.props.customIcon" t-att-style="this.getSelectedColorStyle()"/>
        </t>
        <t t-else="">
            <i class="oi oi-fw py-1" data-icon="colors" t-att-style="this.getSelectedColorStyle()"/>
        </t>
    </button>
</t>

`);
registerTemplate("html_editor.FontFamilySelector", `/html_editor/static/src/main/font/font_family_selector.xml`, `<t t-name="html_editor.FontFamilySelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o_font_family_selector_menu'" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.fontFamilySelector" class="btn btn-light" t-att-title="this.props.title" name="font_family" t-att-disabled="this.props.isDisabled">
                <span class="px-1" t-out="this.props.currentFontFamily.displayName"/>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.props.fontFamilyItems" t-as="item" t-key="item_index">
                        <DropdownItem attrs="{ name: item.nameShort, style: item.fontFamily ? 'font-family: ' + item.fontFamily : '' }" onSelected="() =&gt; this.onSelected(item)" t-on-pointerdown.prevent="() =&gt; {}">
                            <t t-out="item.name"/>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.FontSizeSelector", `/html_editor/static/src/main/font/font_size_selector.xml`, `<t t-name="html_editor.FontSizeSelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o_font_size_selector_menu'" menuRef="this.menuRef" focusToggleOnClosed="false" onStateChanged.bind="this.onDropdownStateChanged">
            <button t-ref="this.fontSizeSelector" class="btn btn-light" t-att-title="this.props.title" name="font_size" t-att-disabled="this.props.isDisabled">
                <IframeInput iframeRef="this.iframeContentRef" inputRef="this.fontSizeInputRef" value="this.state.displayName" inputAttrs="{ name: 'font_size_input', type: 'number', min: 0, max: this.props.maxFontSize }" iframeClass="'o_font_size_selector_iframe'" inputStyle="\`font-family: \${this.fontFamily};\`" onBlur.bind="this.props.onBlur" onClick.bind="this.onClickFontSizeInput" onInput.bind="this.debouncedCustomFontSizeInput" onKeydown.bind="this.onKeyDownFontSizeInput"/>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.items" t-as="item" t-key="item_index">
                        <DropdownItem onSelected="() =&gt; this.onSelected(item)" t-on-pointerdown.prevent="() =&gt; {}">
                            <t t-out="item.name"/>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.FontTypeSelector", `/html_editor/static/src/main/font/font_type_selector.xml`, `<t t-name="html_editor.FontTypeSelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o_font_type_selector_menu'" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.fontTypeSelector" class="btn btn-light" t-att-title="this.props.title" name="font_type" t-att-disabled="this.props.isDisabled">
                <span class="px-1" t-out="this.state.displayName"/>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.items" t-as="item" t-key="item_index">
                        <DropdownItem attrs="{ name: item.tagName }" onSelected="() =&gt; this.onSelected(item)" t-on-pointerdown.prevent="() =&gt; {}">
                            <t t-out="item.name"/>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.TextFieldsIcon", `/html_editor/static/src/main/link/link_popover.xml`, `<t t-name="html_editor.TextFieldsIcon" xml:space="preserve">
        <svg xmlns="http://www.w3.org/2000/svg" class="oe_link_label_icon" height="18px" width="18px" viewBox="0 -960 960 960">
            <path d="M280-160v-520H80v-120h520v120H400v520H280Zm360 0v-320H520v-120h360v120H760v320H640Z"/>
        </svg>
    </t>

    `);
registerTemplate("html_editor.linkPopover", `/html_editor/static/src/main/link/link_popover.xml`, `<t t-name="html_editor.linkPopover" xml:space="preserve">
        <div class="o-we-linkpopover d-flex bg-light overflow-auto shadow" t-on-keydown="this.onKeydown" role="dialog" aria-modal="true" aria-label="Link Popover">
            <div t-if="this.state.editing" class="container-fluid d-flex vertical-center p-2" t-ref="this.editingWrapper">
                <div t-if="this.state.isImage" class="col p-2 o_link_popover_container">
                    <div class="input-group mb-1">
                        <label for="o_linkpopover_url_img" class="o_we_input_label">
                            <span class="oi" data-icon="link"/>
                        </label>
                        <input id="o_linkpopover_url_img" name="o_linkpopover_url_img" t-ref="this.urlRef" class="o_we_href_input_link border-dark-subtle form-control form-control-sm" t-model.proxy="this.state.url" title="URL" placeholder="Type your URL" t-on-keydown="this.onKeydownEnter"/>
                        <button class="o_we_apply_link btn btn-sm btn-primary" t-att-class="{'mx-1': this.state.type ===  ''}" t-on-click="this.onClickApply">Apply</button>
                    </div>
                </div>
                <div t-else="" class="d-flex">
                    <t t-if="this.state.showAdvancedOptions">
                        <div class="o_advance_option_panel">
                            <div class="o_advance_options_grid" style="width: 200px;">
                                <button class="oi btn btn-secondary border-10" data-icon="keyboard_arrow_left" t-on-click="this.toggleAdvancedOptions"/>
                                <t t-foreach="Object.values(this.state.advancedAttributeOptions)" t-as="opt" t-key="opt.label">
                                    <t t-if="!opt.requires or this.state.advancedAttributeOptions[opt.requires].isChecked">
                                        <div class="o_seo_option_row d-flex justify-content-between align-items-center py-1 gap-2">
                                            <span t-att-title="opt.description"><t t-out="opt.label"/></span>
                                            <CheckBox value="opt.isChecked" onChange="this.toggleAdvancedAttr.bind(this, opt.id)"/>
                                        </div>
                                    </t>
                                </t>
                            </div>
                        </div>
                    </t>
                <t t-else="">
                    <div class="col p-2 o_link_popover_container">
                        <div class="input-group mb-2" t-att-class="{'d-none': !this.state.showLabel}">
                            <label for="o_we_label_link" class="o_we_input_label">
                                <t t-call="html_editor.TextFieldsIcon"/>
                            </label>
                            <input t-ref="this.labelRef" id="o_we_label_link" class="o_we_label_link border-dark-subtle form-control form-control-sm" t-model.proxy="this.state.label" title="Label" placeholder="Add a label for your link" t-on-input="this.onChange"/>
                        </div>
                        <div class="input-group mb-2">
                            <label for="o_linkpopover_url" class="o_we_input_label">
                                <span class="oi" data-icon="link"/>
                            </label>
                            <input t-ref="this.urlRef" id="o_linkpopover_url" name="o_linkpopover_url" class="o_we_href_input_link border-dark-subtle form-control form-control-sm" t-model.proxy="this.state.url" title="URL" placeholder="e.g. https://www.odoo.com" t-on-keydown="this.onKeydownEnter" t-on-input="this.onChange"/>
                            <span class="ms-1" t-if="this.props.canUpload">
                                or <button class="btn btn-light btn-sm" t-on-click="this.uploadFile"><i class="oi" data-icon="upload"/></button>
                            </span>

                        </div>
                        <div t-if="this.props.includeStyling" class="input-group mb-2">
                            <Dropdown menuClass="'o-we-link-type-dropdown'">
                                <button name="link_type" class="form-select form-select-sm border-dark-subtle text-start">
                                    <t t-set="selectedItem" t-value="this.buttonTypesData.find(typeData =&gt; typeData.type === this.state.type)"/>
                                    <span t-att-class="selectedItem.className" t-att-style="selectedItem.style" t-out="selectedItem.label"/>
                                </button>
                                <t t-set-slot="content">
                                    <div data-prevent-closing-overlay="true">
                                        <DropdownItem t-if="typeData.type !== 'custom'" t-foreach="this.buttonTypesData" t-as="typeData" t-key="typeData.type" onSelected="() =&gt; this.onSelectedLinkType(typeData.type)" t-on-pointerdown.stop.prevent="() =&gt; {}">
                                            <span t-att-class="typeData.className" t-att-style="typeData.style" t-out="typeData.label"/>
                                        </DropdownItem>
                                    </div>
                                </t>
                            </Dropdown>
                        </div>
                        <div t-if="this.props.includeStyling and this.state.type !== 'link'" class="input-group mb-2">
                            <select name="link_style_size" class="form-select form-select-sm border-dark-subtle" t-model.proxy="this.state.buttonSize" t-on-change="this.onChange" aria-label="Select button size">
                                <option t-foreach="this.buttonSizesData" t-as="buttonSizesData" t-key="buttonSizesData.size" t-att-value="buttonSizesData.size" t-att-selected="this.state.buttonSize === buttonSizesData.size" t-out="buttonSizesData.label"/>
                            </select>
                            <select name="link_style_shape" class="form-select form-select-sm link-style border-dark-subtle" t-model.proxy="this.state.buttonShape" t-on-change="this.onChange" aria-label="Select button shape">
                                <option t-foreach="this.buttonShapesData" t-as="buttonShapeData" t-key="buttonShapeData.shape" t-att-value="buttonShapeData.shape" t-att-selected="this.state.buttonShape === buttonShapeData.shape" t-out="buttonShapeData.label"/>
                            </select>
                        </div>

                        <t t-if="this.props.allowTargetBlank">
                            <t t-if="this.state.isDocument">
                                <CheckBox value="this.state.directDownload" onChange="this.onClickDirectDownload.bind(this)" className="'direct-download-option'">
                                    Direct download
                                </CheckBox>
                            </t>
                        </t>
                        <t t-if="this.props.allowStripDomain and this.isAbsoluteURLInCurrentDomain()">
                            <CheckBox value="this.state.stripDomain" onChange="this.onClickStripDomain.bind(this)" className="'strip-domain-option'">
                                Autoconvert to relative link
                            </CheckBox>
                        </t>
                        <div class="d-flex justify-content-between align-items-center mt-1">
                            <div>
                                <button class="o_we_apply_link btn btn-sm btn-primary" t-att-disabled="!this.state.url" t-on-click="this.onClickApply">Apply</button>
                                <button class="o_we_discard_link btn btn-sm btn-secondary ms-1" t-on-click="this.discard">Discard</button>
                            </div>
                            <div class="d-flex align-items-center gap-1">
                                <a t-if="this.props.canRemove and this.state.url" href="#" class="o_we_remove_link text-dark d-flex me-1" t-on-click.prevent="this.onClickRemove" title="Remove Link">
                                    <i class="oi" data-icon="link_off"/>
                                </a>
                                <button t-if="Object.keys(this.state.advancedAttributeOptions).length" class="btn btn-sm btn-secondary" title="Advanced mode" t-att-disabled="!this.state.url" t-on-click="this.toggleAdvancedOptions">
                                    <i class="oi oi-filled" data-icon="settings"/>
                                </button>
                            </div>
                        </div>
                    </div>
                </t>
            </div>
        </div>
            <div t-else="" class="o_we_link_preview" data-prevent-closing-overlay="true">
                <div class="d-flex flex-column p-2">
                    <div class="d-flex">
                        <span class="o_we_preview_favicon" style="width: 16px; height: 18px">
                            <img t-if="this.state.previewIcon.type === 'imgSrc'" t-att-src="this.state.previewIcon.value" class="align-content-center"/>
                            <span t-elif="this.state.previewIcon.type === 'mimetype'" class="o_image" t-att-data-mimetype="this.state.previewIcon.value"/>
                            <i t-else="" class="oi oi-fw" t-att-class="this.state.previewIcon.class" t-att-data-icon="this.state.previewIcon.value"/>
                        </span>
                        <div class="ms-1" style="width: 264px;">
                            <div class="d-flex">
                                <a href="#" t-att-target="this.linkPreviewTarget" t-attf-href="{{ this.state.url }}" class="o_we_url_link fw-bold flex-grow-1 text-truncate" t-attf-title="{{ this.state.urlTitle }}">
                                    <t t-out="this.state.urlTitle"/>
                                </a>
                                <div class="flex-grow-1 d-flex justify-content-end align-items-center gap-2 me-2">
                                    <a href="#" class="justify-content-center btn-link o_we_replace_title_btn text-600" t-if="this.state.canReplaceTitle and this.state.urlTitle and this.state.label === '' and !this.state.showReplaceTitleBanner" t-on-click="this.onClickReplaceTitle" title="Replace URL with its title">
                                        <i class="oi" data-icon="wand_stars"/>
                                    </a>
                                    <a t-if="this.props.canEdit" href="#" class="o_we_edit_link btn btn-sm btn-secondary" t-on-click="this.onClickEdit" title="Edit Link">Edit</a>
                                </div>
                            </div>
                            <div t-if="this.showUrl" class="text-truncate" style="max-width: 200px; font-size: 12px;">
                                <span t-attf-class="o_we_full_url text-muted o_we_webkit_box" t-attf-title="{{this.state.url}}">
                                    <t t-if="this.state.url" t-out="this.state.url"/>
                                    <t t-else="">No URL specified</t>
                                </span>
                            </div>
                        </div>
                    </div>
                    <div t-if="this.state.imgSrc" class="o_extra_info_card" style="align-self: center; max-width: 235px">
                            <a href="#" target="_blank" t-attf-href="{{this.state.url}}" title="Open in a new tab">
                                <img t-att-src="this.state.imgSrc" class="img-fluid mb-1" style="max-height: 100%;"/>
                            </a>
                    </div>
                    <div t-if="this.state.urlDescription" class="d-flex">
                        <i class="oi align-content-center" data-icon="format_align_right"/>
                        <span class="ms-1 o_we_description_link_preview o_line_clamp" style="font-size: 12px; color: gray;" t-attf-title="{{this.state.urlDescription}}">
                            <t t-out="this.state.urlDescription"/>
                        </span>
                    </div>
                </div>
                <div t-if="this.state.canReplaceTitle and this.state.urlTitle and this.state.label === '' and this.state.showReplaceTitleBanner" class="d-flex align-items-baseline" style="background-color: var(--primary);">
                    <i class="oi oi-fw m-1" data-icon="wand_stars" style="color: var(--o-cc1-btn-primary-text);"/>
                    <span class="me-2 flex-grow-1" style="color: var(--o-cc1-btn-primary-text);font-size: smaller;">Replace URL with its title?</span>
                    <button class=" btn btn-sm btn-primary o_we_replace_title_btn" style="margin: 1px;font-size: smaller;" t-on-click="this.onClickReplaceTitle">Yes</button>
                </div>
            </div>
        </div>
    </t>

`);
registerTemplate("html_editor.ListSelector", `/html_editor/static/src/main/list/list_selector.xml`, `<t t-name="html_editor.ListSelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o-we-toolbar-dropdown'" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.listSelector" class="btn btn-light oi" data-icon="format_list_bulleted" t-att-title="this.props.title" name="list_selector"/>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-set="activeMode" t-value="this.getActiveMode()"/>
                    <t t-foreach="this.props.getButtons()" t-as="button" t-key="button_index">
                        <DropdownItem tag="'button'" attrs="{ name: button.id, title: button.description, 'data-icon': button.icon }" class="{'dropdown-item_active_noarrow btn btn-light oi': true, active: activeMode === button.mode }" onSelected="button.run" t-on-pointerdown.prevent="() =&gt; {}"/>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.ImageAlignSelector", `/html_editor/static/src/main/media/image_align_selector.xml`, `<t t-name="html_editor.ImageAlignSelector" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="'o-we-toolbar-dropdown'" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.imageAlignSelector" class="btn btn-light" t-att-title="this.props.title" name="image_align">
                <span class="oi" t-att-data-icon="this.state.displayIcon"/>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.props.items" t-as="item" t-key="item_index">
                        <DropdownItem tag="'button'" attrs="{ title: item.title, 'data-icon': item.icon }" class="{                                 'dropdown-item_active_noarrow btn btn-light oi': true,                                 active: item.icon === this.state.displayIcon                             }" onSelected="() =&gt; this.onSelected(item)" t-on-pointerdown.prevent="() =&gt; {}"/>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.ImageCrop", `/html_editor/static/src/main/media/image_crop.xml`, `<t t-name="html_editor.ImageCrop" xml:space="preserve">
        <div class="o_we_crop_widget" tabindex="-1" contenteditable="false" t-ref="this.elRef">
            <div class="o_we_cropper_wrapper" t-ref="this.cropperWrapperRef">
                <img class="o_we_cropper_img" t-ref="this.imageRef"/>
                <div class="o_we_crop_buttons text-center mt16 position-fixed o_we_no_overlay" contenteditable="false">
                    <div class="btn-group btn-group-toggle" title="Aspect Ratio" data-bs-toggle="buttons">
                        <t t-foreach="this.aspectRatios" t-as="ratio" t-key="ratio">
                            <t t-set="is_active" t-value="ratio === this.aspectRatio"/>
                            <label t-attf-class="btn #{is_active and 'active' or ''}" t-on-click="() =&gt; this.setAspectRatio(ratio)">
                                <input type="radio"/><t t-out="ratio_value.label"/>
                            </label>
                        </t>
                    </div>
                    <div class="btn-group" role="group">
                        <button type="button" title="Zoom In" t-on-click="() =&gt; this.onZoom(0.1)"><i class="oi oi-fw" data-icon="zoom_in"/></button>
                        <button type="button" title="Zoom Out" t-on-click="() =&gt; this.onZoom(-0.1)"><i class="oi oi-fw" data-icon="zoom_out"/></button>
                    </div>
                    <div class="btn-group" role="group">
                        <button type="button" title="Rotate Left" t-on-click="() =&gt; this.onRotate(-90)"><i class="oi oi-fw" data-icon="undo"/></button>
                        <button type="button" title="Rotate Right" t-on-click="() =&gt; this.onRotate(90)"><i class="oi oi-fw" data-icon="redo"/></button>
                    </div>
                    <div class="btn-group" role="group">
                        <button type="button" title="Flip Horizontal" t-on-click="() =&gt; this.onFlip('scaleX')"><i class="oi" data-icon="arrow_range"/></button>
                        <button type="button" title="Flip Vertical" t-on-click="() =&gt; this.onFlip('scaleY')"><i class="oi" data-icon="height"/></button>
                    </div>
                    <div class="btn-group" role="group">
                        <button type="button" title="Reset Image" t-on-click="this.onReset"><i class="oi" data-icon="refresh"/> Reset Image</button>
                    </div>
                    <div class="btn-group" role="group">
                        <button type="button" t-on-click="this.save" class="btn btn-primary"><i class="oi" data-icon="check" role="presentation"/> Apply</button>
                        <button type="button" t-ref="this.discardButtonRef" t-on-click="this.closeCropper" class="btn btn-danger"><i class="oi" data-icon="close_small" role="presentation"/> Discard</button>
                    </div>
                </div>
            </div>
        </div>
    </t>
`);
registerTemplate("html_editor.ImageToolbarDropdown", `/html_editor/static/src/main/media/image_toolbar_dropdown.xml`, `<t t-name="html_editor.ImageToolbarDropdown" xml:space="preserve">
        <Dropdown state="this.dropdown" menuClass="\`\${this.props.name}_selector\`" menuRef="this.menuRef" focusToggleOnClosed="false">
            <button t-ref="this.imageToolbarBtn" t-att-title="this.props.title" class="btn btn-light">
                <t t-if="this.props.icon.includes('.')" t-call="{{ this.props.icon }}"/>
                <i t-else="" class="oi oi-fw" t-att-data-icon="this.props.icon"/>
                <t t-if="this.state &amp;&amp; this.state.displayName" t-out="this.state.displayName"/>
            </button>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.items" t-as="item" t-key="item_index">
                        <DropdownItem class="'user-select-none'" onSelected="() =&gt; this.onSelected(item)">
                            <t t-out="item.name"/>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.ImageTransformation", `/html_editor/static/src/main/media/image_transformation.xml`, `<t t-name="html_editor.ImageTransformation" xml:space="preserve">
        <div class="transfo-container" t-ref="this.transfoContainer" t-on-mousedown.prevent="this.mouseDown">
            <div class="transfo-controls" t-ref="this.transfoControls">
                <div class="transfo-rotator oi-lg">
                    <i class="oi oi-2x oi-filled" data-icon="circle"/>
                    <i class="oi" data-icon="rotate_right"/>
                </div>
                <div style="top: 0%; left: 0%; cursor: nw-resize;" class="transfo-scaler transfo-scaler-tl"/>
                <div style="top: 0%; left: 100%; cursor: ne-resize;" class="transfo-scaler transfo-scaler-tr"/>
                <div style="top: 100%; left: 100%; cursor: se-resize;" class="transfo-scaler transfo-scaler-br"/>
                <div style="top: 100%; left: 0%; cursor: sw-resize;" class=" transfo-scaler transfo-scaler-bl"/>
                <div style="top: 0%; left: 50%; cursor: n-resize;" class="transfo-scaler transfo-scaler-tc"/>
                <div style="top: 100%; left: 50%; cursor: s-resize;" class="transfo-scaler transfo-scaler-bc"/>
                <div style="top: 50%; left: 0%; cursor: w-resize;" class="transfo-scaler transfo-scaler-ml"/>
                <div style="top: 50%; left: 100%; cursor: e-resize;" class="transfo-scaler transfo-scaler-mr"/>
                <div style="border: 0; width: 0px; height: 0px; top: 50%; left: 50%; margin: 0px;" class="transfo-scaler transfo-scaler-mc" t-ref="this.transfoCenter"/>
            </div>
        </div>
    </t>
`);
