registerTemplate("html_editor.TableMenu", `/html_editor/static/src/main/table/table_menu.xml`, `<t t-name="html_editor.TableMenu" xml:space="preserve">
        <Dropdown menuClass="'m-0'" position="this.props.type === 'column' ? 'bottom' : 'right'" state="this.props.dropdownState" bottomSheet="false">
            <button type="button" t-ref="this.menuRef" t-att-data-type="this.props.type" class="o-we-table-menu oi" t-attf-class="{{ this.props.type === 'column' ? 'w-100' : 'h-100 px-0' }}" t-attf-data-icon="{{ this.props.type === 'column' ? 'more_horiz' : 'more_vert' }}" title="Click to open options&#10;Drag to move" t-on-pointerdown.prevent="() =&gt; {}"/>
            <t t-set-slot="content">
                <div t-on-pointerdown.stop="() =&gt; {}">
                    <t t-foreach="this.items" t-as="item" t-key="item_index">
                        <DropdownItem onSelected="() =&gt; !item.disable and this.onSelected(item)">
                            <div class="user-select-none d-flex align-items-center" t-att-name="item.name" t-att-title="item.disable ? item.tooltip : ''" t-att-class="item.disable ? 'disabled text-muted' : ''">
                                <span t-if="item.icon" class="oi text-center" t-att-class="item.iconClass" style="width:16px;" t-att-data-icon="item.icon"/>
                                <span class="ms-2" t-out="item.text"/>
                            </div>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>
`);
registerTemplate("html_editor.TablePicker", `/html_editor/static/src/main/table/table_picker.xml`, `<t t-name="html_editor.TablePicker" xml:space="preserve">
        <div class="o-we-tablepicker bg-light p-1 my-1" t-on-click="this.insertTable" t-on-mousedown.stop="">
            <t t-foreach="new Array(this.state.rows + 1)" t-as="row" t-key="row_index">
                <div class="o-we-row d-flex">
                    <t t-foreach="new Array(this.state.cols + 1)" t-as="col" t-key="col_index">
                        <div class="o-we-cell" t-att-class="{'active': col_index lt this.state.cols and row_index lt this.state.rows}" t-on-mouseenter="() =&gt; this.updateSize(col_index + 1, row_index + 1)"/>
                    </t>
                </div>
            </t>
            <div class="text-center"><t t-out="this.state.cols"/>x<t t-out="this.state.rows"/></div>
        </div>
    </t>
`);
registerTemplate("html_editor.MobileToolbar", `/html_editor/static/src/main/toolbar/mobile_toolbar.xml`, `<t t-name="html_editor.MobileToolbar" xml:space="preserve">
        <div t-ref="this.toolbarRef" class="o-toolbar-above-keyboard">
            <Toolbar state="this.props.state" getSelection="this.props.getSelection" focusEditable="this.props.focusEditable" class="this.props.class"/>
        </div>
    </t>
`);
registerTemplate("html_editor.Toolbar", `/html_editor/static/src/main/toolbar/toolbar.xml`, `<t t-name="html_editor.Toolbar" xml:space="preserve">
        <div t-ref="this.toolbarEl" class="o-we-toolbar d-flex align-items-center m-0" t-att-class="this.props.class" style="overflow-x: auto; overflow-y:hidden" t-att-data-namespace="this.state.namespace" data-prevent-closing-overlay="true" t-on-keydown="this.onKeyDown">
            <t t-foreach="this.state.buttonGroups" t-as="buttonGroup" t-key="buttonGroup.id">
                <span class="o-we-toolbar-vertical-separator"/>
                <div class="btn-group" t-att-name="buttonGroup.id">
                    <t t-foreach="buttonGroup.buttons" t-as="button" t-key="button.id">
                            <t t-if="button.Component">
                                <t t-component="button.Component" t-props="button.props" title="button.description" getSelection.bind="this.props.getSelection" isDisabled="'isDisabled' in button.props ? button.props.isDisabled : !!button.isDisabled"/>
                            </t>
                            <button t-else="" class="btn btn-light" t-att-class="{                                     active: button.isActive,                                     disabled: button.isDisabled,                                 }" t-att-disabled="button.isDisabled" t-att-title="button.description" t-att-name="button.id" t-on-click="() =&gt; this.onButtonClick(button)">
                                <t t-if="button.icon">
                                    <t t-if="button.icon.includes('.')" t-call="{{ button.icon }}"/>
                                    <span t-else="" t-attf-class="oi oi-fw {{button.iconClass || ''}}" t-att-data-icon="button.icon"/>
                                </t>
                                <span t-if="button.text" t-out="button.text"/>
                            </button>
                    </t>
                </div>
            </t>
        </div>
    </t>
`);
registerTemplate("html_editor.LanguageSelector", `/html_editor/static/src/main/translate/language_selector.xml`, `<t t-name="html_editor.LanguageSelector" xml:space="preserve">
        <t t-if="this.state.languages.length === 1">
            <t t-call="html_editor.translateButton" onClick="() =&gt; this.onSelected({languageCode: this.state.languages[0][0], languageName: this.state.languages[0][1]})">
            </t>
        </t>
        <Dropdown t-else="" menuRef="this.menuRef">
            <t t-call="html_editor.translateButton" onClick="() =&gt; {}">
            </t>
            <t t-set-slot="content">
                <div data-prevent-closing-overlay="true">
                    <t t-foreach="this.state.languages" t-as="language" t-key="language[0]">
                        <DropdownItem class="'user-select-none'" onSelected="() =&gt; this.onSelected({languageCode: language[0], languageName: language[1]})">
                            <div class="lang" t-out="language[1]"/>
                        </DropdownItem>
                    </t>
                </div>
            </t>
        </Dropdown>
    </t>

    `);
