registerTemplate("html_editor.CodeToolbar", `/html_editor/static/src/others/embedded_components/backend/syntax_highlighting/code_toolbar.xml`, `<t t-name="html_editor.CodeToolbar" xml:space="preserve">
        <div t-att-class="this.props.isActive ? 'show' : ''" class="o_code_toolbar">
            <div data-prevent-closing-overlay="true">
                <Dropdown menuClass="'o_language_selector'" focusToggleOnClosed="false">
                    <button class="btn" t-att-title="this.languages[this.props.currentLanguage]" name="language">
                        <span class="px-1" t-out="this.languages[this.props.currentLanguage]"/>
                        <i class="oi" data-icon="arrow_drop_down"/>
                    </button>
                    <t t-set-slot="content">
                        <t t-foreach="Object.entries(this.languages)" t-as="language" t-key="language[0]">
                            <DropdownItem attrs="{ name: language[1] }" onSelected="() =&gt; this.props.onLanguageChange(language[0])" t-on-pointerdown.prevent="() =&gt; {}">
                                <t t-out="language[1]"/>
                            </DropdownItem>
                        </t>
                    </t>
                </Dropdown>
                <CopyButton content="this.props.getContent" copyText.translate="Copy" successText.translate="Code copied to the clipboard." t-on-pointerdown.prevent="() =&gt; {}"/>
                <button class="text-nowrap btn" name="wrap" t-on-click="this.props.toggleCodeWrap" title="Wrap the code">
                    <span class="mx-1 oi oi-rotate-90" data-icon="subdirectory_arrow_right"/>
                    <span>Wrap</span>
                </button>
                <button class="text-nowrap btn" t-on-click="this.props.convertToParagraph">
                    <span class="oi mx-1" data-icon="format_paragraph" title="Convert to paragraph"/>
                </button>
            </div>
        </div>
    </t>
`);
registerTemplate("html_editor.EmbeddedSyntaxHighlighting", `/html_editor/static/src/others/embedded_components/backend/syntax_highlighting/syntax_highlighting.xml`, `<t t-name="html_editor.EmbeddedSyntaxHighlighting" xml:space="preserve">
        <CodeToolbar target="this.props.host" currentLanguage="this.embeddedState.languageId" getContent="() =&gt; this.textareaRef().value" onLanguageChange="this.onLanguageChange.bind(this)" convertToParagraph="this.props.convertToParagraph" toggleCodeWrap="this.toggleCodeWrap.bind(this)"/>
        <pre t-ref="this.preRef"/>
        <textarea t-ref="this.textareaRef" class="o_prism_source" contenteditable="true" placeholder="Code" t-on-input="this.onInput" t-on-scroll="this.onScroll" t-on-keydown="this.onKeydown" t-on-focus="this.props.onTextareaFocus"/>
    </t>
`);
