registerTemplate("mail.Tabs", `/mail/static/src/core/common/tabs.xml`, `<t t-name="mail.Tabs" xml:space="preserve">
    <div t-attf-class="o-mail-Tabs d-flex bg-view h-100 w-100" t-ref="this.rootRef" t-att-class="{'o-mail-Tabs-vertical': this.props.direction === 'v', 'flex-column o-mail-Tabs-horizontal': this.props.direction === 'h'}">
        <div class="position-relative d-flex bg-100 flex-shrink-0" t-att-class="{'flex-row mh-25': this.props.direction === 'h', 'border-end flex-column mw-25': this.props.direction === 'v'}">
            <button t-if="this.scrollState.hasScrollbar" t-att-disabled="!this.scrollState.canScrollBefore" class="btn border-transparent o-mail-Tabs-scroller flex-shrink-0 bg-100 rounded-0" t-on-click="() =&gt; this.scroll(-1)"><i class="oi smaller" t-attf-data-icon="{{ this.props.direction === 'v' ? 'keyboard_arrow_up' : 'chevron_backward' }}"/></button>
            <nav class="o-mail-Tabs-scrollContainer d-flex flex-grow-1 overflow-auto gap-2 p-2" t-att-class="{'flex-row': this.props.direction === 'h', 'flex-column': this.props.direction === 'v'}" t-ref="this.navRef"/>
            <button t-if="this.scrollState.hasScrollbar" t-att-disabled="!this.scrollState.canScrollAfter" class="btn border-transparent o-mail-Tabs-scroller flex-shrink-0 rounded-0 bg-100" t-on-click="() =&gt; this.scroll(1)"><i class="oi smaller" t-attf-data-icon="{{ this.props.direction === 'v' ? 'keyboard_arrow_down' : 'chevron_forward'}}"/></button>
        </div>
        <div class="o-mail-Tabs-content overflow-auto flex-grow-1 o-scrollbar-thin">
            <t t-call-slot="default"/>
        </div>
    </div>
</t>

`);
