registerTemplate("mail.ThreadIcon", `/mail/static/src/core/common/thread_icon.xml`, `<t t-name="mail.ThreadIcon" xml:space="preserve">
        <t t-set="class" t-value="'o-mail-ThreadIcon d-flex ' + this.props.className + ' ' + this.attClassObjectToString({             'oi-lg': this.props.size === 'lg' or this.props.size === 'large',             'o-xsmaller': this.props.size === 'sm' or this.props.size === 'small',         })"/>
        <t t-set="attr" t-value="{ 'class': class }"/>
        <t name="extra"/>
        <t t-if="this.channel?.channel_type === 'channel'">
            <div t-if="!this.channel.group_public_id" class="oi o-fs-small" data-icon="public" t-att="attr" title="Public Channel"/>
        </t>
        <t t-elif="this.channel?.channel_type === 'group'">
            <t name="group"/>
        </t>
        <t t-elif="this.channel?.showImStatus and this.channel?.channel_type?.includes('chat') and this.correspondent">
            <t name="chat">
                <t name="chat_static">
                    <ImStatus t-if="this.correspondent.imStatusUI" className="class" member="this.correspondent" size="this.props.size" typing="this.props.typing"/>
                    <div t-else="" class="d-flex rounded-circle bg-inherit">
                        <i class="oi oi-fw" t-att="attr" t-att-class="this.defaultChatIcon.class" t-att-data-icon="this.defaultChatIcon.icon" t-att-title="this.defaultChatIcon.title"/>
                    </div>
                </t>
            </t>
        </t>
    </t>

`);
registerTemplate("discuss.BlurPerformanceWarning", `/mail/static/src/discuss/call/common/blur_performance_warning.xml`, `<t t-name="discuss.BlurPerformanceWarning" xml:space="preserve">
        <CallDropdown class="'z-2'" menuClass="'o-discuss-BlurPerformanceWarning shadow bg-warning-subtle border-warning-subtle'" openByDefault="true">
            <div class="o-discuss-BlurPerformanceWarning-button btn bg-warning-subtle p-1 rounded-circle position-absolute top-0 start-0" title="Background Blur Performance Warning">
                <i class="oi oi-fw" data-icon="warning"/>
            </div>
            <t t-set-slot="content">
                <div class="position-relative p-3 rounded text-dark" style="min-width:275px;">
                    <div class="position-absolute top-0 end-0 m-2 cursor-pointer" t-on-click="this.onClickClose" title="Dismiss warning">
                        <i class="oi" data-icon="close_small"/>
                    </div>
                    <div>
                        <strong>Performance Warning:</strong><br/>
                        Hardware acceleration is disabled. Blur effect impacts performance significantly.
                    </div>
                </div>
            </t>
        </CallDropdown>
    </t>
`);
registerTemplate("discuss.Call", `/mail/static/src/discuss/call/common/call.xml`, `<t t-name="discuss.Call" xml:space="preserve">
        <div class="o-discuss-Call user-select-none position-relative gap-2" t-att-class="{             'o-fullSize': this.isFullSize,             'o-compact': this.props.compact and !this.isMobileOs,             'o-minimized': this.minimized,             'position-relative o-mx-0_5 o-mt-0_5 p-1': !this.rtc.isFullscreen and !this.props.isPip,             'rounded-2': !this.rtc.isFullscreen and !this.props.isPip and this.isActiveCall,             'o-hasVideo': this.channel.videoCount &gt; 0,             'o-selfInCall': this.isActiveCall,         }" t-ref="this.rootRef">
            <div class="o-discuss-Call-main d-flex flex-column align-items-center justify-content-center position-relative overflow-x-hidden overflow-y-auto o-scrollbar-thin h-100" t-on-mouseleave="this.onMouseleaveMain">
                <PttAdBanner t-if="!this.props.compact"/>
                <BlurPerformanceWarning t-if="this.store.settings.blurPerformanceWarning"/>
                <CallPresentationBar t-if="this.rtc.selfSession and this.isAnyonePresenting"/>
                <div class="o-discuss-Call-mainCards position-relative overflow-hidden w-100 flex-grow-1 o-min-height-0" t-att-class="{'mt-1': this.minimized, 'o-discuss-Call-sidebar': this.hasSidebar}" t-on-click="() =&gt; this.showOverlay()" t-on-mousemove="this.onMousemoveMain" t-ref="this.gridRef">
                    <t t-set="stage" t-value="this.stageContent"/>
                    <CallParticipantCard t-foreach="stage.surfaces" t-as="surface" t-key="surface.key" cardData="surface.data" className="this.surfaceClassName(surface)" isSidebarItem="surface.data.placement === 'sidebar'" isCropped="this.state.cropsTiles and surface.data.placement === 'main' and surface.data.type !== 'screen'" inset="surface.data.placement === 'inset'" minimized="this.minimized" channel="this.channel"/>
                    <span t-if="stage.hasMoreCards" class="oi ps-1 pe-1 o-discuss-Call-moreIndicator position-absolute d-flex align-items-center justify-content-center text-white-50" data-icon="more_horiz" t-att-data-surface="'__more__'"/>
                </div>


                <div t-if="this.props.hasOverlay and (this.state.overlay or !this.isControllerFloating)" class="o-discuss-Call-overlay d-flex justify-content-center w-100 pb-1" t-att-class="{ 'o-isFloating position-absolute z-2 bottom-0 pb-2': this.isControllerFloating }">
                    <div t-on-mousemove="this.onMousemoveOverlay">
                        <CallActionList channel="this.channel" compact="this.props.compact or this.props.isPip"/>
                    </div>
                </div>
                <div t-if="this.topNotifications.length" class="o-discuss-Call-topNotifications position-absolute d-flex flex-column start-50 translate-middle-x top-0" t-att-class="{ 'pt-4': this.rtc.isFullscreen, 'pt-2': !this.rtc.isFullscreen }">
                    <span class="o-discuss-Call-notification text-bg-light shadow-lg rounded-1 m-1" t-att-class="{ 'p-3 fs-4': this.rtc.isFullscreen, 'p-2': !this.rtc.isFullscreen }" t-foreach="this.topNotifications" t-as="notification" t-key="notification.id" t-out="notification.text"/>
                </div>
                <div t-if="this.bottomNotifications.length" class="o-discuss-Call-bottomNotifications position-absolute d-flex flex-column-reverse start-0 bottom-0" t-att-class="{ 'ps-5 pb-5': this.rtc.isFullscreen, 'ps-2 pb-2': !this.rtc.isFullscreen }">
                    <span class="o-discuss-Call-notification text-bg-light shadow-lg rounded-1 m-1" t-att-class="{ 'p-3 fs-4': this.rtc.isFullscreen, 'p-2': !this.rtc.isFullscreen }" t-foreach="this.bottomNotifications" t-as="notification" t-key="notification.id" t-out="notification.text"/>
                </div>
                <CallRecordingIndicator t-if="this.rtc.isRecording()" className="'position-absolute z-3 bottom-0 start-0 m-2'"/>
                <div t-if="!this.isActiveCall" class="w-100"><hr class="border-top border-dark" t-att-class="{ 'ms-2 me-3': this.env.inDiscussApp, 'mx-1': this.env.inChatWindow }" style="--border-opacity: .75;"/></div>
            </div>
        </div>
    </t>

`);
registerTemplate("discuss.CallActionList", `/mail/static/src/discuss/call/common/call_action_list.xml`, `<t t-name="discuss.CallActionList" xml:space="preserve">
        <div class="o-discuss-CallActionList d-flex flex-column justify-content-center" t-attf-class="{{ this.props.className }}" t-att-class="{ 'o-inMeetingView': this.env.inMeetingView }" t-ref="this.root">
            <div class="o-discuss-CallActionList-bar d-flex align-items-center justify-content-between" t-att-class="{ 'w-100 ps-2 pe-2': this.isSmall }">
                <ActionList actions="this.actions" inline="true" hasBtnBg="true"/>
            </div>
        </div>
    </t>

`);
registerTemplate("discuss.CallContextMenu", `/mail/static/src/discuss/call/common/call_context_menu.xml`, `<t t-name="discuss.CallContextMenu" xml:space="preserve">
        <div class="o-discuss-CallContextMenu d-flex flex-column" t-att-class="{ 'gap-4': this.ui.isSmall, 'gap-1': !this.ui.isSmall }">
            <t t-if="!this.isSelf">
                <button class="btn o-discuss-CallContextMenu-item d-flex align-items-center gap-2 w-100 px-2 py-1 border-0 rounded text-reset text-start cursor-pointer" t-on-click="this.togglePin">
                    <i class="oi oi-fw opacity-75" data-icon="push_pin"/><t t-if="this.isPinned">Unpin</t><t t-else="">Pin</t>
                </button>
                <div class="o-discuss-CallContextMenu-row d-flex align-items-center gap-2 w-100 px-2 py-1">
                    <button class="btn o-discuss-CallContextMenu-muteToggle border-0 p-0 lh-1 cursor-pointer text-reset" t-on-click="this.toggleLocallyMute" t-att-title="this.muteLabel" t-att-aria-label="this.muteLabel">
                        <i class="oi oi-fw" t-att-data-icon="(this.isLocallyMuted or this.state.rangeVolume === 0) ? 'volume_off' : 'volume_up'"/>
                    </button>
                    <div class="position-relative flex-grow-1">
                        <input type="range" min="0.0" max="1" step="0.01" class="form-range h-auto" t-att-value="this.props.rtcSession.getEffectiveVolume()" t-model.proxy="this.state.rangeVolume" t-on-change="this.onChangeVolume"/>
                        <output t-out="\`\${Math.round(this.state.rangeVolume * 200)}%\`" class="o-mail-CallContextMenu-volumeTooltip fw-bold rounded" t-attf-style="--progress:{{this.state.rangeVolume * 100}}%;"/>
                    </div>
                </div>
                <button t-if="this.canModerate" class="btn o-discuss-CallContextMenu-item o-danger d-flex align-items-center gap-2 w-100 px-2 py-1 border-0 rounded text-start cursor-pointer" t-on-click="this.onClickRemoveFromCall">
                    <i class="oi oi-fw oi-filled" data-icon="cancel"/>Remove from call
                </button>
            </t>
            <t t-if="this.debugMode.isActive() and !this.isSelf and this.rtc.connectionType === this.rtcConnectionTypes.P2P">
                <hr class="w-100 border-top"/>
                <div><span class="fw-bolder">RTC Session ID: </span><t t-out="this.props.rtcSession.id"/></div>
                <div><span class="fw-bolder">Connection type: </span><t t-out="this.rtc.connectionType"/></div>
                <div><span class="fw-bolder">To peer: </span><t t-out="this.outboundConnectionTypeText"/></div>
                <div><span class="fw-bolder">From peer: </span><t t-out="this.inboundConnectionTypeText"/></div>
                <div><span class="fw-bolder">Connection: </span><t t-out="this.state.peerStats.connectionState"/></div>
                <div><span class="fw-bolder">ICE connection: </span><t t-out="this.state.peerStats.iceConnectionState"/></div>
                <div><span class="fw-bolder">ICE: </span><t t-out="this.state.peerStats.iceState"/></div>
                <div><span class="fw-bolder">DTLS: </span><t t-out="this.state.peerStats.dtlsState"/></div>
                <div><span class="fw-bolder">Data channel: </span><t t-out="this.state.peerStats.dataChannelState"/></div>
                <div t-if="this.props.rtcSession.audioError"><span class="fw-bolder">Audio player: </span><t t-out="this.props.rtcSession.audioError"/></div>
                <div t-if="this.props.rtcSession.videoError"><span class="fw-bolder">Video player: </span><t t-out="this.props.rtcSession.videoError"/></div>
                <hr class="w-100 border-top"/>
                <div><span class="fw-bolder">ICE gathering: </span><t t-out="this.state.peerStats.iceGatheringState"/></div>
                <div><span class="fw-bolder">Packets sent: </span><t t-out="this.state.peerStats.packetsSent"/></div>
                <div><span class="fw-bolder">Packets received: </span><t t-out="this.state.peerStats.packetsReceived"/></div>
                <div><span class="fw-bolder">Log step: </span><t t-out="this.props.rtcSession.logStep"/></div>
            </t>
            <t t-elif="this.debugMode.isActive() and this.isSelf and this.rtc.connectionType === this.rtcConnectionTypes.SERVER">
                <div><span class="fw-bolder">Connection type: </span><t t-out="this.rtc.connectionType"/></div>
                <div><span class="fw-bolder">RTC Session ID: </span><t t-out="this.props.rtcSession.id"/></div>
                <hr class="w-100 border-top"/>
                <div><span class="fw-bolder">Upload: </span><t t-out="this.outboundConnectionTypeText"/></div>
                <div><span class="fw-bolder">up ICE: </span><t t-out="this.state.uploadStats.iceState"/></div>
                <div><span class="fw-bolder">up DTLS: </span><t t-out="this.state.uploadStats.dtlsState"/></div>
                <div><span class="fw-bolder">Packets sent: </span><t t-out="this.state.uploadStats.packetsSent"/></div>
                <div><span class="fw-bolder">available bitrate: </span><t t-out="this.state.uploadStats.availableOutgoingBitrate"/></div>
                <hr class="w-100 border-top"/>
                <div><span class="fw-bolder">Download: </span><t t-out="this.inboundConnectionTypeText"/></div>
                <div><span class="fw-bolder">down ICE: </span><t t-out="this.state.downloadStats.iceState"/></div>
                <div><span class="fw-bolder">down DTLS: </span><t t-out="this.state.downloadStats.dtlsState"/></div>
                <div><span class="fw-bolder">Packets received: </span><t t-out="this.state.downloadStats.packetsReceived"/></div>
                <t t-if="this.state.producerStats.audio">
                    <hr class="w-100 border-top"/>
                    <div><span class="fw-bolder">microphone</span></div>
                    <div><span class="fw-bolder">codec: </span><t t-out="this.state.producerStats.audio.codec"/></div>
                    <div><span class="fw-bolder">clock rate: </span><t t-out="this.state.producerStats.audio.clockRate"/></div>
                </t>
                <t t-if="this.state.producerStats.camera and this.props.rtcSession.is_camera_on">
                    <hr class="w-100 border-top"/>
                    <div><span class="fw-bolder">camera</span></div>
                    <div><span class="fw-bolder">codec: </span><t t-out="this.state.producerStats.camera.codec"/></div>
                    <div><span class="fw-bolder">clock rate: </span><t t-out="this.state.producerStats.camera.clockRate"/></div>
                </t>
                <t t-if="this.state.producerStats.screen and this.props.rtcSession.is_screen_sharing_on">
                    <hr class="w-100 border-top"/>
                    <div><span class="fw-bolder">screen</span></div>
                    <div><span class="fw-bolder">codec: </span><t t-out="this.state.producerStats.screen.codec"/></div>
                    <div><span class="fw-bolder">clock rate: </span><t t-out="this.state.producerStats.screen.clockRate"/></div>
                </t>
            </t>
        </div>
    </t>
`);
registerTemplate("discuss.CallDropdown", `/mail/static/src/discuss/call/common/call_dropdown.xml`, `<t t-name="discuss.CallDropdown" xml:space="preserve">
        <t t-call-slot="default"/>
        <div t-if="this.isOpen()" class="o-discuss-CallDropdown" t-att-class="this.props.class">
            <div t-ref="this.menuRef" t-on-click="this.onClickMenu" class="o-discuss-CallDropdown-content o-dropdown--menu dropdown-menu d-block" t-att-class="this.props.menuClass">
                <t t-call-slot="content"/>
            </div>
        </div>
    </t>

`);
registerTemplate("discuss.CallInvitation", `/mail/static/src/discuss/call/common/call_invitation.xml`, `<t t-name="discuss.CallInvitation" xml:space="preserve">
        <div class="o-discuss-CallInvitation align-self-center o-rounded-bubble overflow-hidden shadow-sm" t-att-class="{'o-preview-open': this.state.showCameraPreview, 'o-chat': this.props.channel.channel_type === 'chat', 'border border-light': !this.store.isOdooWhiteTheme}">
            <div class="d-flex flex-colum d-flex flex-column">
                <div class="o-discuss-CallInvitation-main" t-ref="this.root">
                    <div class="ms-1 position-relative d-flex justify-content-between p-2">
                        <div class="d-flex align-items-center" style="min-width: 0;">
                            <div class="o-mail-CallInvitation-avatar flex-shrink-0 cursor-pointer d-flex align-items-center justify-content-center rounded-circle overflow-hidden" t-att-class="{'bg-primary': !this.inviter}" t-on-click="() =&gt; this.props.channel.open({ focus: true })" t-att-title="this.avatarTitle">
                                <img t-if="this.inviter" class="object-fit-cover h-100 w-100" t-att-src="this.inviter.avatarUrl" alt="Avatar"/>
                                <i t-else="" class="oi oi-filled" data-icon="phone"/>
                            </div>
                            <div class="ms-2 me-3 flex-grow-1 overflow-hidden">
                                <p class="o-discuss-CallInvitation-channelName m-0 fw-bold small text-truncate" t-out="this.props.channel.displayName"/>
                                <p class="o-discuss-CallInvitation-description m-0 fst-italic smaller text-truncate pe-1">Incoming call...</p>
                            </div>
                        </div>
                        <div class="d-flex align-items-center flex-shrink-0 gap-2">
                            <ActionList actions="this.acceptOrRejectActions" inline="true" hasBtnBg="true"/>
                            <ActionList actions="this.otherActions" inline="true"/>
                        </div>
                    </div>
                    <div class="o-discuss-CallInvitation-cameraPreview" t-att-class="{'o-opened': this.state.showCameraPreview}">
                        <CallPreview activateCamera="this.state.activateCamera" activateMicrophone="this.state.activateMicrophone" onSettingsChanged="(settings) =&gt; this.onCallSettingsChanged(settings)"/>
                    </div>
                </div>
            </div>
        </div>
    </t>
`);
registerTemplate("discuss.CallInvitations", `/mail/static/src/discuss/call/common/call_invitations.xml`, `<t t-name="discuss.CallInvitations" xml:space="preserve">
        <div t-if="this.store.ringingChannels.length &gt; 0" class="o-discuss-CallInvitations position-fixed top-0 end-0 d-flex flex-column p-2">
            <t t-foreach="this.store.ringingChannels" t-as="channel" t-key="channel.localId">
                <CallInvitation channel="channel"/>
            </t>
        </div>
    </t>

`);
registerTemplate("discuss.CallMenu", `/mail/static/src/discuss/call/common/call_menu.xml`, `<t t-name="discuss.CallMenu" xml:space="preserve">
        <div class="dropdown" t-attf-class="{{ this.className }}" t-ref="this.root">
            <button t-if="this.rtc.channel" class="user-select-none dropdown-toggle o-no-caret o-dropdown--narrow px-0 rounded-pill border-0 position-relative" t-att-title="this.buttonTitle" t-on-click="this.rtc.channel.open">
                <div class="o-discuss-CallMenu-buttonContent d-flex align-items-center btn-group rounded-pill overflow-visible" t-att-class="{ 'o-isOdooCommunity': !this.isEnterprise }">
                    <div class="o-discuss-CallMenu-channelInfo text-truncate btn btn-group-item border-0 m-0 p-0 d-flex align-items-center gap-1 ps-2 pe-1 rounded-4 rounded-end-0 align-self-stretch bg-inherit" role="button" title="Open Conversation">
                        <span class="position-relative small bg-transparent">
                            <img class="rounded-2 object-fit-cover" t-att-src="this.rtc.channel.avatarUrl" alt="Thread Image" style="width: 20px; height: 20px"/>
                        </span>
                        <span class="text-truncate small" t-out="this.rtc.channel.displayName"/>
                    </div>
                    <Dropdown state="this.dropdownState">
                        <button class="o-discuss-CallMenu-actionsButton btn border-0 text-body rounded-4 rounded-start-0 m-0 o-pe-0_5" t-att-class="{ 'o-dropdown-open': this.dropdownState.isOpen }" title="Select Actions">
                            <i class="oi o-fs-small" t-att-data-icon="this.icon" t-att-class="this.lastSelfActionAttClass"/>
                            <div class="o-discuss-CallMenu-actionsControl position-relative d-flex align-items-center justify-content-center">
                                <span t-if="this.lastSelfAction?.tags.includes('WARNING_BADGE')" class="o-discuss-CallMenu-warningBadge fw-bold badge p-1 rounded-circle d-inline justify-content-center align-items-center o-discuss-warningBadge bg-warning">
                                    <i t-if="this.lastSelfAction?.badgeIcon" class="oi" t-att-class="this.lastSelfAction.badgeIconClass" t-att-data-icon="this.lastSelfAction.badgeIcon"/><span t-elif="this.lastSelfAction.badgeText" t-out="this.lastSelfAction.badgeText"/>
                                </span>
                                <div t-else="" class="o-discuss-CallMenu-actionsAudioBars">
                                    <TalkingAudioBars t-if="this.rtc.selfSession" session="this.rtc.selfSession"/>
                                </div>
                                <i class="o-discuss-CallMenu-actionsChevron oi" t-att-data-icon="this.dropdownState.isOpen ? 'keyboard_arrow_up' : 'keyboard_arrow_down'"/>
                            </div>
                        </button>
                        <t t-set-slot="content">
                            <ActionList actions="this.callActions.actionsComputed" dropdown="true"/>
                        </t>
                    </Dropdown>
                </div>
                <span class="o-discuss-inCallIcon fw-bold rounded-circle d-flex justify-content-center align-items-center position-absolute z-3 bg-white" style="font-size: 0.6rem; top: -4px; left: -2px; padding: 1px;">
                    <i class="oi oi-fw bg-inherit rounded-circle opacity-75" data-icon="volume_up_f"/>
                </span>
            </button>
        </div>
    </t>

`);
registerTemplate("discuss.CallParticipantCard", `/mail/static/src/discuss/call/common/call_participant_card.xml`, `<t t-name="discuss.CallParticipantCard" xml:space="preserve">
        <div class="o-discuss-CallParticipantCard d-flex flex-column align-items-center justify-content-center mh-100 mw-100" t-att-class="{                 'cursor-pointer': (this.props.inset and this.isActiveRtcSession) or !this.rtcSession,                 'o-isTalking': !this.props.minimized and this.isTalking,                 'o-isInvitation opacity-50': !this.rtcSession,                 'o-inset': this.props.inset,                 'pe-none': this.rtc.screenTrack and !this.rtc.screenTrack.enabled,                 'p-1 rounded-1': !this.isActiveRtcSession,             }" t-att-aria-label="this.name" t-att-data-is-context-menu-available="this.isContextMenuAvailable" t-att-data-surface="this.props.cardData.key" t-attf-class="{{ this.props.className }}" t-on-click="this.onClick" t-on-mousedown="this.onMouseDown" t-on-touchmove="this.onTouchMove" t-on-touchend="this.onTouchEnd" t-ref="this.root" t-att-style="this.cardBgStyle">

            <t t-if="!this.props.isSidebarItem and this.props.cardData.type === 'screen' and this.rtc.screenTrack and !this.rtc.screenTrack.enabled">
                <div class="d-flex flex-column align-items-center">
                    <h1 class="o-text-white">You are Presenting</h1>
                    <div class="o-text-white fs-5 text-center d-flex flex-column">
                        <span>To avoid an infinity mirror, don't share your entire screen or browser window.<br/>Share just a tab or a different window instead.</span>
                    </div>
                    <div class="d-flex mt-4 gap-3">
                        <button class="btn btn-primary rounded-pill px-5 pe-auto" t-on-click.stop="() =&gt; (this.rtc.screenTrack.enabled = true)" aria-label="Show My Screen Anyway">Show My Screen Anyway</button>
                        <button class="btn btn-secondary rounded-pill px-5 pe-auto" t-on-click.stop="() =&gt; this.rtc.toggleVideo('screen', false)" aria-label="Stop Presenting">Stop Presenting</button>
                    </div>
                </div>
            </t>
            <CallParticipantVideo t-elif="this.hasVideo" session="this.rtcSession" type="this.props.cardData.type" inset="this.props.inset" isCropped="this.props.isCropped"/>
            <div t-else="" class="o-discuss-CallParticipantCard-avatar d-flex align-items-center justify-content-center h-100 w-100 rounded-3" t-att-class="{ 'o-minimized': this.props.minimized, 'o-isRemoteVideo': this.isRemoteVideo, 'o-selfInCall': this.isActiveCall }" draggable="false">
                <img t-if="!this.showRemoteWarning" alt="Avatar" class="rounded-circle border-5 object-fit-cover" t-att-src="this.channelMember?.avatarUrl" draggable="false" t-att-class="{                     'o-isTalking': this.isTalking,                     'o-isInvitation': !this.rtcSession,                     'h-50': this.props.minimized or this.props.isSidebarItem or this.props.inset,                     'h-100': !this.isActiveCall,                     'o-minimized': this.props.minimized,                     'o-small': this.isSmall,                 }"/>
            </div>

            <t t-if="this.isActiveCall and this.rtcSession">

                <span class="o-discuss-CallParticipantCard-overlay z-1 position-absolute bottom-0 start-0 d-flex overflow-hidden rounded-3 m-2" t-att-class="{'o-proportional-container w-75': this.isSmall, 'o-m-2_5': !this.isSmall and this.store.meetingViewOpened }" t-att-data-connection-state="this.rtcSession.connectionState">
                    <span t-if="!this.props.minimized" class="rounded-pill text-truncate o-proportional-text o-discuss-CallParticipantCard-overlayBottomName o-discuss-CallParticipantCard-iconBlackBg gap-2 d-flex align-items-center" t-att-class="{'o-minimized px-2 o-py-0_5 small': this.isSmall, 'o-px-2_5 py-1': !this.isSmall }">
                        <span class="text-truncate" t-out="this.name"/>
                        <span t-if="this.rtcSession.is_deaf or this.rtcSession.is_muted" class="h-75 border-end opacity-25" style="--border-color: white;"/>
                        <i t-if="this.rtcSession.is_deaf" class="oi" data-icon="hearing_disabled"/>
                        <i t-elif="this.rtcSession.is_muted" class="oi" data-icon="mic_off"/>
                    </span>
                </span>
                <span t-if="this.showRemoteWarning" class="o-discuss-CallParticipantCard-overlay o-proportional-container z-1 w-50 position-absolute d-flex align-items-center justify-content-center overflow-hidden">
                    <span class="fw-bold p-1 rounded-3 o-video-text o-proportional-text">Video visible in the call tab</span>
                </span>

                <div class="o-discuss-CallParticipantCard-overlay position-absolute top-0 end-0 d-flex align-items-center w-50 flex-row-reverse gap-1 m-2" t-att-class="{ 'o-m-2_5': !this.isSmall and this.store.meetingViewOpened, 'mw-25': this.props.isSidebarItem or this.props.inset }">
                    <Dropdown t-if="this.isContextMenuAvailable and (this.contextMenuDropdownState.isOpen or (!this.isMobileOS and this.rootHover.isHover) or (this.isMobileOS and !this.props.minimized))" state="this.contextMenuDropdownState" menuClass="this.attClassObjectToString({                         'd-flex o-discuss-CallParticipantCard-contextMenu': true,                         [this.store.discussDropdownMenuClass(this)]: true,                         'w-100': this.isMobileOS,                     })">
                        <button class="o-discuss-CallParticipantCard-contextButton h-100 d-flex justify-content-center align-items-center rounded-pill border-0 o-py-0_5 o-py-1_5 m-0 smaller o-discuss-CallParticipantCard-iconBlackBg" title="Participant options">
                            <i class="oi" data-icon="expand_more"/>
                        </button>
                        <t t-set-slot="content">
                            <CallContextMenu rtcSession="this.rtcSession"/>
                        </t>
                    </Dropdown>
                    <span t-if="this.isPinned" class="d-flex flex-column justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized p-1': this.isSmall, 'p-2': !this.isSmall }" title="Pinned" aria-label="Pinned">
                        <i class="oi" data-icon="push_pin"/>
                    </span>
                    <span t-if="this.isLocallyMuted" class="d-flex flex-column justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized p-1': this.isSmall, 'p-2': !this.isSmall }" title="Muted for you" aria-label="Muted for you">
                        <i class="oi oi-fw o-py-0_5" data-icon="volume_off"/>
                    </span>
                    <div t-if="!this.props.minimized and this.hasVideo and this.props.cardData.type !== 'screen'" class="o-mt-0_5 o-me-0_5">
                        <TalkingAudioBars t-if="this.isTalking" asPill="true" session="this.rtcSession"/>
                    </div>
                </div>

                <div class="o-discuss-CallParticipantCard-overlay position-absolute bottom-0 end-0 d-flex w-50 m-2 flex-row-reverse" t-att-class="{ 'mw-25': this.props.isSidebarItem or this.props.inset, 'o-m-2_5': !this.isSmall and this.store.meetingViewOpened }">
                    <span t-if="this.hasRaisingHand" class="d-flex flex-column justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized p-1': this.isSmall, 'p-2': !this.isSmall }" title="raising hand" aria-label="raising hand">
                        <i class="oi" data-icon="back_hand"/>
                    </span>
                    <span t-if="this.hasMediaError" class="d-flex flex-column justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized p-1': this.isSmall, 'p-2': !this.isSmall }" title="media player Error" t-on-click.stop="this.onClickReplay">
                        <i t-if="this.rootHover.isHover" class="oi text-danger" data-icon="redo"/>
                        <i t-else="" class="oi text-danger" data-icon="warning"/>
                    </span>
                </div>

                <div class="o-discuss-CallParticipantCard-overlay position-absolute bottom-0 start-0 d-flex w-50 m-2" t-att-class="{ 'mw-25': this.props.isSidebarItem or this.props.inset, 'o-m-2_5': !this.isSmall and this.store.meetingViewOpened }">
                    <span t-if="this.rtcSession.is_muted and !this.rtcSession.is_deaf and (this.props.inset or this.props.minimized)" class="d-flex justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized o-px-0_5': this.isSmall }" title="muted" aria-label="muted">
                        <i class="oi oi-fw py-1" data-icon="mic_off"/>
                    </span>
                    <span t-if="this.rtcSession.is_deaf and (this.props.inset or this.props.minimized)" class="d-flex justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized o-px-0_5': this.isSmall }" title="deaf" aria-label="deaf">
                        <i class="oi oi-fw py-1" data-icon="hearing_disabled"/>
                    </span>
                </div>

                <div class="o-discuss-CallParticipantCard-overlay position-absolute top-0 start-0 d-flex w-50 m-2" t-att-class="{ 'mw-25': this.props.isSidebarItem or this.props.inset, 'o-m-2_5': !this.isSmall and this.store.meetingViewOpened }">
                    <span t-if="this.showConnectionState" class="d-flex flex-column justify-content-center rounded-circle o-discuss-CallParticipantCard-iconBlackBg" t-att-class="{'o-minimized p-1': this.isSmall, 'p-2': !this.isSmall }" t-att-title="this.rtcSession.connectionState">
                        <i class="oi text-warning" data-icon="warning"/>
                    </span>
                    <span t-if="this.showLiveLabel or (this.rtcSession.is_screen_sharing_on and this.props.minimized and !this.isOfActiveCall)" class="user-select-none rounded-pill smaller text-bg-danger d-flex align-items-center o-px-1_5 fw-bold" t-att-class="{ 'o-px-2_5 py-1': !this.isSmall }" title="live" aria-label="live">
                        LIVE
                    </span>
                </div>
            </t>
        </div>
    </t>
`);
registerTemplate("discuss.CallParticipantVideo", `/mail/static/src/discuss/call/common/call_participant_video.xml`, `<t t-name="discuss.CallParticipantVideo" xml:space="preserve">
        <div class="o-discuss-CallParticipantVideo w-100 h-100 rounded-3 d-flex align-items-center overflow-hidden">
            <video class="w-100 h-100" t-att-class="{                     'o-inset': this.props.inset,                     'object-fit-cover': this.props.isCropped,                 }" t-att-type="this.props.type" t-att-data-facing-mode="this.store.settings.cameraFacingMode" playsinline="true" autoplay="true" muted="true" t-on-loadedmetadata="this.onVideoLoadedMetaData" t-ref="this.root"/>
        </div>
    </t>
`);
registerTemplate("discuss.CallPermissionDeniedDialog", `/mail/static/src/discuss/call/common/call_permission_denied_dialog.xml`, `<t t-name="discuss.CallPermissionDeniedDialog" xml:space="preserve">
        <PermissionPromptDialog title="''" size="'md'" close="this.props.close" illustrationPosition="'left'" contentClass="'o-discuss-CallPermissionDeniedDialog'">
            <t t-set-slot="illustration">
                <t t-call="discuss.CallPermissionDeniedDialog.illustrationAnimated"/>
            </t>
            <t t-set-slot="instructions">
                <h2 t-out="this.title"/>
                <ol class="ps-3 fs-6 d-flex flex-column gap-2 text-muted">
                    <li t-out="this.stepOneText"/>
                    <li t-out="this.stepTwoText"/>
                </ol>
            </t>
        </PermissionPromptDialog>
    </t>

    `);
