registerTemplate("discuss.CallPermissionDialog", `/mail/static/src/discuss/call/common/call_permission_dialog.xml`, `<t t-name="discuss.CallPermissionDialog" xml:space="preserve">
        <PermissionPromptDialog title="''" close="this.props.close" illustrationPosition="'right'">
            <t t-set-slot="illustration">
                <t t-call="discuss.CallPermissionDialogImg"/>
            </t>
            <t t-set-slot="instructions">
                <h2 t-out="this.permissionPrompt" t-ref="this.rootRef"/>
                <p class="text-muted" t-out="this.permissionNote"/>
            </t>
            <t t-set-slot="footer">
                <button class="btn btn-primary" t-if="this.props.suggestAllMedias and this.rtc.cameraPermission !== 'granted' and this.rtc.microphonePermission !== 'granted'" t-on-click="this.onClickUseMicAndCamera">Use microphone and camera</button>
                <button class="btn btn-secondary" t-on-click="this.props.media === 'microphone' ? this.onClickUseMicrophone : this.onClickUseCamera" t-out="this.secondaryActionText"/>
            </t>
        </PermissionPromptDialog>
    </t>

    `);
