registerTemplateExtension("mail.Thread", `/mail/static/src/discuss/core/common/thread_patch.xml`, `<t t-inherit="mail.Thread" t-inherit-mode="extension" xml:space="preserve">
        <xpath expr="//div[hasclass('o-mail-Thread')]" position="before">
            <span t-if="!this.env.inChatter and this.channel?.showUnreadBanner" class="o-mail-Thread-banner d-flex cursor-pointer smaller fw-bold border border-warning overflow-hidden flex-shrink-0" t-att-class="{ 'rounded-4': !this.env.inChatWindow }">
                <t t-set="alertClass" t-value="'alert alert-warning m-0 border-0 rounded-0 o-mail-Thread-bannerHover py-1'"/>
                <span t-attf-class="{{ alertClass }} flex-grow-1" t-on-click="this.onClickUnreadMessagesBanner" t-out="this.newMessageBannerText"/>
                <span t-attf-class="{{ alertClass }}" t-on-click="() =&gt; this.props.thread.markAsRead()">Mark as Read<i class="ms-2 oi" data-icon="check_box"/></span>
            </span>
        </xpath>
    </t>
`);
registerTemplate("discuss.GifPicker", `/mail/static/src/discuss/gif_picker/common/gif_picker.xml`, `<t t-name="discuss.GifPicker" xml:space="preserve">
        <div class="o-discuss-GifPicker d-flex flex-column" t-attf-class="{{ this.props.className }}" t-att-class="{ 'h-100': this.props.mobile }" t-on-focusin="() =&gt; this.state.focused = true" t-on-focusout="() =&gt; this.state.focused = false">
            <div t-if="!this.store.hasGifPickerFeature and this.store.self_user?.is_admin" class="d-flex flex-column align-items-center justify-content-center m-3 h-100">
                <span class="o-discuss-GifPicker-bigEmoji">🧑‍🍳🌶️</span>
                <span class="fs-5 text-muted text-center">Want to spice up your conversations with GIFs? Turn on this feature in settings.</span>
                <button class="btn btn-primary mt-3" t-on-click="this.onClickOpenDiscussSetting">Enable GIFs</button>
            </div>
            <t t-else="">
                <div class="o-EmojiPicker-search d-flex align-items-center m-2 rounded">
                    <i t-if="!this.state.showCategories" aria-label="back" t-on-click="this.openCategories" class="oi cursor-pointer p-2 fs-5" data-icon="west"/>
                    <span class="d-flex mx-1 w-100 rounded o-active">
                        <t t-call="discuss.GifPicker.searchInput"/>
                        <i class="oi p-2 fs-5 rounded-start-0 rounded-3 o-active" data-icon="search" title="Search..." role="img" aria-label="Search..."/>
                    </span>
                </div>
                <div class="o-discuss-GifPicker-content overflow-y-auto overflow-x-hidden ps-2 pe-3 pb-2 h-100" t-ref="this.scrollerRef">
                    <div t-if="this.state.loadingError" class="text-center">
                        <span class="o-discuss-GifPicker-error d-block">😵‍💫</span>
                        <span class="fs-5 text-muted d-block">Failed to load gifs...</span>
                        <span t-if="this.store.self_user?.is_admin" class="small text-warning opacity-75 d-block mx-2"><i class="oi me-1" data-icon="warning" role="img"/>If you were using a Tenor API key, please replace it with a Klipy API key in the General Settings.</span>
                    </div>
                    <div t-if="this.state.showCategories and !this.state.loadingError" class="row row-cols-2 gy-2 gx-2" aria-label="list">
                        <div t-if="this.store.self_user" class="col">
                            <div class="position-relative ratio ratio-16x9 cursor-pointer rounded overflow-hidden" t-on-click="this.onClickFavoritesCategory" aria-label="list-item">
                                <img t-if="this.state.favorites.gifs.length &gt; 0" class="o-discuss-GifPicker-category" t-att-src="this.state.favorites.gifs[0].media_formats.tinygif.url" loading="lazy" alt="GIF Favorites"/>
                                <div class="position-absolute w-100 h-100 top-0 start-0 text-center o-text-white align-middle fs-2 o-bg-black bg-opacity-50">
                                    Favorites
                                </div>
                            </div>
                        </div>
                        <t t-if="this.state.categories.length === 0">
                            <t t-foreach="Array(10)" t-as="i" t-key="i_index">
                                <div class="col">
                                    <div class="position-relative ratio ratio-16x9 cursor-pointer rounded overflow-hidden" aria-label="list-item">
                                        <div class="position-absolute w-100 h-100 top-0 start-0 text-center o-text-white align-middle fs-2 o-bg-black bg-opacity-50"/>
                                    </div>
                                </div>
                            </t>
                        </t>
                        <t t-else="">
                            <t t-foreach="this.state.categories" t-as="category" t-key="category_index">
                                <div class="col">
                                    <div class="position-relative ratio ratio-16x9 cursor-pointer rounded overflow-hidden" t-on-click="() =&gt; this.onClickCategory(category)" aria-label="list-item">
                                        <img class="o-discuss-GifPickerCategory-img img-fluid" t-att-src="category.image" loading="lazy" alt="GIF Category"/>
                                        <div class="position-absolute w-100 h-100 top-0 start-0 text-center o-text-white align-middle fs-2 o-bg-black bg-opacity-50">
                                            <t t-out="category.name"/>
                                        </div>
                                    </div>
                                </div>
                            </t>
                        </t>
                    </div>
                    <t t-if="!this.state.showCategories">
                        <div class="d-flex gap-1">
                            <div>
                                <t t-foreach="this.state.evenGif.gifs" t-as="gif" t-key="gif_index">
                                    <t t-call="discuss.GifPicker.gif"/>
                                </t>
                            </div>
                            <div>
                                <t t-foreach="this.state.oddGif.gifs" t-as="gif" t-key="gif_index">
                                    <t t-call="discuss.GifPicker.gif"/>
                                </t>
                            </div>
                        </div>
                        <div t-if="this.state.loadingGif" class="text-center fs-6 h-100 d-flex flex-column justify-content-center">
                            <i class="oi oi-spin" data-icon="autorenew"/>
                        </div>
                        <div t-elif="this.showFavorite and this.state.evenGif.gifs.size === 0 and this.state.oddGif.gifs.size === 0" class="d-flex flex-column h-100 align-items-center justify-content-center text-center text-muted gap-2">
                            <i class="o-discuss-GifPicker-noFavoritesIcon oi oi-filled o-yellow fs-1" data-icon="star"/>
                            <span class="fs-5">So uhh... maybe go favorite some GIFs?</span>
                        </div>
                    </t>
                </div>
            </t>
        </div>
    </t>

    `);
registerTemplate("discuss.GifPicker.gif", `/mail/static/src/discuss/gif_picker/common/gif_picker.xml`, `<t t-name="discuss.GifPicker.gif" xml:space="preserve">
        <div class="o-discuss-Gif position-relative mt-1 fs-5 cursor-pointer rounded overflow-hidden">
            <i t-if="this.store.self_user" class="position-absolute top-0 end-0 me-3 mt-3 p-2 o-bg-black bg-opacity-75 oi cursor-pointer opacity-0" t-att-class="{ 'o-text-white': !this.isFavorite(gif_value), 'oi-filled o-starred': this.isFavorite(gif_value) }" data-icon="star" t-on-click="() =&gt; this.onClickFavorite(gif_value)"/>
            <Gif class="'img-fluid'" style="this.style" alt="'GIF'" onClick="() =&gt; this.onClickGif(gif_value)" src="gif_value.media_formats.tinygif.url" loading="'lazy'" paused="!this.state.focused"/>
        </div>
    </t>

    `);
